quests[47315] = { id = 47315, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf in die Dünen", description = "Was auch immer Rakera aufgedeckt hat, war wohl wichtig genug, um ihr 'n Todesurteil in den Sanden einzubrock'n. \n\nWir müss'n nach Vol'dun, um sie zu find'n. \n\nWir dürf'n nich' zulass'n, dass ihr Wissen über Jakra'zet mit ihr in den Dünen verlor'n geht.", sourceObjective = "Fliegt in die Wüste von Vol'dun und sucht dort nach Kriegswache Rakera.", completion = "Diese Schlangenleute werden für das bezahlen, was sie meinem Zuhause angetan haben!", sourceObjectiveStatus = "unverified-source-field" }
quests[47316] = { id = 47316, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimnisse im Sand", description = "Ich habe dieses Notizbuch im Sand vergraben gefunden. \n\nKiro wollte es ins Feuer werfen.\n\n\"In unserem Wagen ist kein Platz für ein Tagebuch, Meerah. Welchen praktischen Nutzen hätte es für uns?\"\n\nSagt es ihm nicht, aber ich finde es faszinierend! Könnt Ihr Euch vorstellen, was für Geheimnisse es birgt? \n\nEs fehlen eine ganze Menge Seiten, aber ich wette, dass Ihr sie da draußen in den Dünen finden könnt!", sourceObjective = "Findet die fehlenden Seiten aus dem Notizbuch.", progress = "Was habt Ihr gefunden?", completion = "Das is' Rakeras Handschrift. Ich würd sie überall wiedererkenn'.", sourceObjectiveStatus = "unverified-source-field" }
quests[47317] = { id = 47317, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suche nach Überlebenden", description = "Schön, Euch in Sicherheit zu seh'n, aber was is' mit den ander'n? Wurd'n die von der Wüste verschluckt?\n\nIhr müsst zurück zur Absturzstelle geh'n und rausfind'n, ob die ander'n überlebt ham.\n\nIch werd mich mal umhör'n, vielleicht weiß das Fuchsvolk ja was über Rakera.", sourceObjective = "Sucht die Absturzstelle und deren Umgebung nach Überlebenden ab.", completion = "Jorana hat die Gefahr'n gekannt, als sie in die Wüste gezog'n is', aber ich fühl mich trotzdem schuldig an ihr'm Tod.\n\nIch kann bloß hoff'n, dass es Tarkaj irgendwie in Sicherheit geschafft hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[47319] = { id = 47319, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heilendes Gift", description = "Meerah hat Eure Freundin in den Dünen gefunden. Der Blitzschlag hätte sie fast umgebracht. Ohne Behandlung wird sie nicht lange überleben.\n\nDie Stiche der Wespen im Wald sind schmerzhaft, aber ihr Gift hat dafür heilende Eigenschaften.\n\nAus ihren Drüsensäcken kann ich entnehmen, was ich brauche.\n\nMit einer ordentlichen Menge an Gift sollte es uns gelingen, die Wunden Eurer Freundin zu lindern.", sourceObjective = "Sammelt 15 Sandstachelgiftdrüsen.", progress = "Habt Ihr die Drüsen dabei? Ohne sie können wir Eurer Freundin nicht heilen.", completion = "<Schnell untersucht Kiro die Drüsen.>\n\nDie sind genau richtig.", sourceObjectiveStatus = "unverified-source-field" }
quests[47320] = { id = 47320, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein beruhigender Balsam", description = "Hier habt Ihr den versprochenen Balsam, der die Verletzungen Eurer Gefährtin heilen sollte. \n\nWendet ihn großzügig auf alle offenen Wunden an.\n\nDie Wirkung sollte sofort zu spüren sein.", sourceObjective = "Wendet den regenerierenden Balsam bei Klingenwache Kaja an.", completion = "Ham uns diese Kreaturen geholf'n?\n\nIch kann mich bloß noch dran erinnern, wie wir über das Imperium der Sethrak geflog'n sind. Dann hat's plötzlich hell geblitzt, un' dann war alles dunkel...", sourceObjectiveStatus = "unverified-source-field" }
quests[47321] = { id = 47321, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampf um den Krimskrams", description = "Nisha sagte mir, dass Ihr auf der Suche nach einer Verbannten hier seid. Mit Namen Rakera? \n\nWir kennen sie zwar nicht, aber wir können Euch vielleicht helfen, sie zu finden. \n\nWenn Ihr uns helft, helfen wir Euch. Abgemacht?\n\nWir leben vom Sammeln. Wir tauschen die Sachen ein, die wir finden, aber die Sethrak, die unsere Höhlen überfallen haben, sind mit unseren Sachen auf und davon. \n\nIch wusste immer, dass sie rücksichtslos sind, aber so viel Gier hatte ich ihnen nicht zugetraut.\n\nHolt uns zurück, was die Sethrak uns genommen haben, und wir geben Euch sicheres Geleit durch die Dünen.", sourceObjective = "Sammelt 6 Teile Krimskrams von den Sethrak im Schlangenschlund ein.", progress = "Wenn Ihr uns helft, helfen wir Euch. Abgemacht?", completion = "Ihr seid weitaus kompetenter, als Ihr ausseht.", sourceObjectiveStatus = "unverified-source-field" }
quests[47322] = { id = 47322, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flucht mit Unterstützung", description = "Die Sethrak sind vielleicht stark, aber wir sind schnell. Also, zumindest Mekaru und ich.\n\nWir haben es gerade so eben in einem Stück zurück in den Wagen geschafft. \n\nDie anderen hatten wohl nicht so viel Glück. Wir haben eine Weile gewartet, aber nichts mehr von ihnen gehört. \n\nKönntet Ihr vielleicht nach unseren Freunden Ausschau halten, wenn Ihr da reinmarschiert?", sourceObjective = "Befreit Hakasi und Kipp aus dem Schlangenschlund.", completion = "Danke, {name}. Wir verdanken Euch unser Leben.", sourceObjectiveStatus = "unverified-source-field" }
quests[47324] = { id = 47324, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unwahrscheinliche Verbündete", description = "Ich glaube, das ist einer der Schlüssel der Hüter! Aber genau weiß das nur Vorrik. \n\nWir müssen sofort zum Tempel. \n\nMein Pterrordax kann uns hinbringen, wenn Ihr bereit seid, aber wir müssen uns beeilen.", sourceObjective = "Fliegt zum Sanktum der Ergebenen.", completion = "Wir dürfen den Tempel nicht den Treulosen überlassen!", sourceObjectiveStatus = "unverified-source-field" }
quests[47327] = { id = 47327, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Antwort auf ihre Angriffe", description = "Die Angriffe der Sethrak auf unsere Höhlen dürfen nicht ungestraft bleiben. \n\nSie müssen lernen, dass sich nicht alle Bewohner der Wüste so leicht geschlagen geben. \n\nDas Einzige, was die Sethrak verstehen, ist Blut... Also werden wir ihnen ihre Lektion in genau dieser Sprache erteilen.\n\n<Nisha hält inne und schaut Euch fragend an, als zweifele sie daran, dass Ihr sie versteht.>\n\nIch will damit sagen, dass wir die Sethrak hier töten müssen, und zwar alle.", sourceObjective = "Tötet Sethrak in den Verlassenen Höhlen.", completion = "Ihr Blut strömt die Dünen bis zu ihrer Festung hinab. Die Sethrak werden es sich zweimal überlegen, bevor sie unsere Höhlen noch mal angreifen.", sourceObjectiveStatus = "unverified-source-field" }
quests[47329] = { id = 47329, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Erbe der Blutwächter", description = "Ich grüße Euch, {name}.\n\nMein Vater, der Oberste Prüfer Tae'thelan Blutwächter, hat mich hierhergeschickt, um die Ausgrabungen aller Fossilien, Relikte und Artefakte in dieser Gegend zu beaufsichtigen.\n\nMeine Quellen haben berichtet, dass hier ein Objekt vergraben sein soll, das der Horde von großem Nutzen sein könnte.\n\nIch benötige Eure Hilfe, um es zu bergen. Diese Nachtgeborenen sind nicht sonderlich geschickt und machen sich auch nicht so gern die Hände schmutzig.\n\nKönntet Ihr vielleicht mit gutem Beispiel vorangehen?", sourceObjective = "Helft Prüferin Tae'shara Blutwächter dabei, ein Fossil von Xibala zu bergen.", completion = "Ihr habt es getan! Mit eigenen Händen! Das ist bemerkenswert, denn die Nachtgeborenen geben sich alle Mühe, diese Art von Arbeit zu vermeiden.", sourceObjectiveStatus = "unverified-source-field" }
quests[47330] = { id = 47330, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flüstern einer verängstigten Welt", description = "Champion, Magni braucht Eure Hilfe!\n\nDer Sprecher hat eine Nachricht für Euch, vielleicht von Azeroth selbst. Er hat wohl Probleme damit, sie zu verstehen, doch er kann Euch das sicher besser erklären.\n\nIhr findet ihn im Sholazarbecken in Nordend. Sicher werdet Ihr schon bald von ihm hören.", sourceObjective = "Trefft Euch mit Magni im Sholazarbecken und hört Euch die Warnung an.", completion = "Diese Warnung ist tatsächlich ein beängstigendes Omen, {name}. Das Schicksal Azeroths scheint mit jenem von Argus, der Heimatwelt der Legion, verbunden zu sein.\n\nWir müssen den Plan des Dunklen Titanen aufdecken! Ich glaube, die Verbindung des Sprechers mit der Weltseele ist hier von größter Bedeutung.\n\nBleibt wachsam, Rächer. Wir müssen uns auf Magnis Rat verlassen... und auf den von Azeroth selbst.", sourceObjectiveStatus = "unverified-source-field" }
quests[47331] = { id = 47331, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[47332] = { id = 47332, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der nächste Schritt", description = "Prinzessin Talanji will in den Norden nach Nazmir reisen. Die Bluttrolle dort sind eine Bedrohung, die ihr Vater ihrer Meinung nach nicht ernst nehmen will.\n\nGeneral Jakra'zet verabscheut die Horde, daher kann man ihm nicht trauen. Solange er an der Macht ist, wird die Stadt nie sicher sein.\n\nIhr werdet auch König Rastakhan in Zuldazar auf Eure Seite bringen müssen. Die Stadt ist groß und birgt viele Geheimnisse.", sourceObjective = "Wählt Euren nächsten Schritt in Zandalar.", sourceObjectiveStatus = "unverified-source-field" }
quests[47416] = { id = 47416, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatten des Triumvirats", description = "Talgaths Worte sind von größerer Bedeutung, als er wohl selbst wissen konnte. Indem er ein letztes Mal versuchte, mich niederzustrecken, hat er uns die Antwort gegeben.\n\nDas Wappen des Wissens ist im Sitz des Triumvirats versteckt. Und es ist nicht unbewacht.\n\nWenn ich mich nicht täusche, stellt sich uns eine größere Bedrohung, als wir sie je befürchtet haben.\n\nEin dunkler Naaru.\n\nLasst uns zur Vindikaar zurückkehren. Wir werden von dort aus unsere nächsten Schritte planen.", sourceObjective = "Kehrt zur Vindikaar zurück.", completion = "Ich war in Sorge um L'ura, aber dies ist... unvorstellbar.\n\nWie sehr muss sie gelitten haben...", sourceObjectiveStatus = "unverified-source-field" }
quests[47418] = { id = 47418, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wachstumsschmerzen", description = "Diese Trolle lassen sich eine großartige Möglichkeit entgehen! Sie beschweren sich immer darüber, zu wenige Tiere zu haben, um über die Runden zu kommen, aber haben sie es schon mal mit Massenhaltung versucht? Natürlich nicht!\n\nMit meinem Wachstumshormon für Terrorhörner würden ihre Pferche blitzschnell überquellen! Natürlich gäbe es dann Probleme mit Krankheiten und Exkrementen, aber die ließen sich ja lösen.\n\nHahaha, das wird einfach fantastisch!", sourceObjective = "Füttert Euer Junges mit dem Wachstumshormon für Terrorhörner.", progress = "Und? Hat Euer Junges schon das WFT probiert?", completion = "Oh, Mann! Das hat ja noch besser funktioniert, als ich dachte! Ich werde ein Vermögen verdienen!", sourceObjectiveStatus = "unverified-source-field" }
quests[47422] = { id = 47422, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Höhentroll", description = "Es gibt 'ne gute Nachricht. Wir ham die Quelle der Verderbnis gefund'n.\n\nDie schlechte Nachricht is', dass es sich dabei um ein Ritual auf dem Gipfel von Zanchul handelt.\n\nDiese Ketzer woll'n irgendeinen Terrortroll da oben mit ihrer Blutmagie stärk'n.\n\nDarüber, wie der an uns vorbei auf den Gipfel gekommen is', werd'n Raal un' ich bestimmt noch jahrelang diskutier'n.\n\nKommt, lasst uns die Ketzer aufhalt'n.", sourceObjective = "Tötet Dregada.", progress = "Was für 'ne Weisheit hatte der Loapriester für Euch?", completion = "Dieses Blut werd ich in meinem Tempel nich' zulass'n!", sourceObjectiveStatus = "unverified-source-field" }
quests[47423] = { id = 47423, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verbotene Praktiken", sourceObjective = "Findet und tötet 9 Purpurkultisten auf der Terrasse der Auserwählten.", completion = "Was? Diese geifernde Übereifrige beschuldigt mich, nich' meinen Beitrag zu leist'n? Pah!", sourceObjectiveStatus = "unverified-source-field" }
quests[47424] = { id = 47424, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - First Chromie Saved" }
quests[47428] = { id = 47428, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Miezi?", description = "Ihr müsst unseren letzten Gast vor der Teestunde finden!\n\nSchmuserchen treibt sich furchtbar gerne im Wald herum. Ich würde wetten, dass wir ihn dort finden!", sourceObjective = "Finde Schmuserchen im Wald von Schluchtbach.", completion = "Miiiau?\n\n<Ihr habt Schmuserchen gefunden, aber von Anneke fehlt jede Spur.>", sourceObjectiveStatus = "unverified-source-field" }
quests[47430] = { id = 47430, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mondkinbeobachtung", description = "<Arra bedeutet Euch, dass Ihr die anderen Mondkin in der Nähe beobachten sollt.>", sourceObjective = "Versucht etwas zu lernen, indem Ihr die tanzenden, mondfeuernden und schlafenden Mondkinküken in der Nähe beobachtet.", progress = "Dok-dok-GRAAK!", completion = "<Arra scheint sehr zufrieden mit dem zu sein, was Ihr gelernt habt.>", sourceObjectiveStatus = "unverified-source-field" }
quests[47431] = { id = 47431, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sammeln des Lichts", description = "Alleria und ich würden nur zu gern mehr Zeit mit unserem Sohn verbringen, aber wir können nicht länger warten, {name}. Wir müssen jetzt zuschlagen.\n\nDie Armee des Lichts ist versprengt, aber nicht besiegt. Alle Überlebenden werden sich nahe der Absturzstelle der Xenedar aufhalten. Wenn wir doch noch siegen wollen, müssen wir sie sammeln und Xe'ra retten.\n\nNach dem Ausschalten der Grubenlords sollte der Weg zur Xenedar etwas sicherer sein. Trefft mich so schnell es Euch möglich ist im Krokullager.", sourceObjective = "Trefft Turalyon im Krokullager.", completion = "Wir haben eine Stellung gesichert. Sehr gut.\n\nJetzt können wir den Kampf zu ihnen tragen!", sourceObjectiveStatus = "unverified-source-field" }
quests[47432] = { id = 47432, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abgemacht ist abgemacht", description = "Jetzt, da Ihr 'nen Loaschutzpatron für Eure Zeit in Zuldazar erwählt habt, solltet Ihr dem König von Eurer Entscheidung erzähl'n.\n\nEr wird Wohlgefall'n daran find'n, dass Ihr Euch für die große Pa'ku entschied'n habt.", sourceObjective = "Sprecht mit König Rastakhan.", completion = "Ihr habt Euch also für den Pfad von Pa'ku entschied'n. Mögen Euch die Winde immer gewog'n sein.\n\nIch persönlich folg dem Pfad von Rezan, dem Teufelssaurierloa der Könige. Wir hab'n allerdings seit Jahren nich' mehr gesproch'n.\n\nVielleicht sollte ich ihn wieder mal besuch'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[47433] = { id = 47433, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Offensive Defensive", description = "Ich wette, Loti wollte, dass Ihr alle Trolle tötet, die mit Blutmagie zu tun hatt'n, richtig? Aber damit is' die Sache noch nich' erledigt.\n\nDie Blutmagie is' schon uralt un' unsre Leute sin' ihr erst erlegen, seit die Mauern an der nördlichen Grenze gefallen sin'.\n\nKommt, wir mach'n 'nen kleinen Ausflug und patrouillier'n die Grenze zu Nazmir. Von da kommen all diese bösen Gedank'n.", sourceObjective = "Patrouilliert den Himmel mit Hexfürst Raal.", completion = "Oh, diese Hakennasenstoßzahnvisage wollte Euch also mit 'nem kleinen Ausflug beeindruck'n, ja?", sourceObjectiveStatus = "unverified-source-field" }
quests[47434] = { id = 47434, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ordnung wiederherstellen", description = "\"Irgendwas fühlt sich komisch an\"? Sonst hat Raal nichts gesagt?\n\nSein Pterrordaxschwarm flattert überall im Hof von Zanchul rum. Die sin' verrückt geword'n.\n\nVerscheucht sie, bevor sie sich oder andre verletz'n.", sourceObjective = "Verscheucht 20 Pterrordaxjunge.", completion = "Warum verscheucht Ihr meinen Schwarm?", sourceObjectiveStatus = "unverified-source-field" }
quests[47435] = { id = 47435, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pterrorfax'n dicke", description = "Der Hof von Zanchul wurd von Pterrordaxen überrannt, die durch irgendein dunkles Ritual verrückt geword'n sin'. Da is' irgend'ne dunkle Macht am Werk, un' man kann nich' sagen, wer oder was dahintersteckt.\n\nIch muss die Quelle dafür find'n. In der Zwischenzeit zieht mit Gonks Gunst in den Kampf. Seine Verbündeten werden Euch helf'n. Tötet diese verrückt'n Pterrordaxe.\n\nWenn das erledigt is', sagt Ihr Raal, dass er seinen Schwarm unter Kontrolle halt'n soll.", sourceObjective = "Tötet 6 blutlüsterne Pterrordaxe.", completion = "Musstet Ihr so viele töt'n?", sourceObjectiveStatus = "unverified-source-field" }
quests[47437] = { id = 47437, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit voller Hingabe", description = "Ja, ich weiß, dass diese Situation ernst is', aber sie hat Euch die Macht von ihrem Loa überlass'n? Klingt für mich, als würd Loti sich mehr um die Rekrutierung kümmern als um die Bedrohung durch die Bluttrolle.\n\nIm Tempel hinter mir gibt's drei Wächter. Als ich dort reinging, wollt'n die mich töt'n. Mich!\n\nIrgendwer hat unsre eig'nen Wächter verderbt.\n\nHier, ich werd Euch die Stimme von meinem eigenen Loa, Pa'ku dem Pterrordax, leih'n. Verwendet sie, um diese Verderbnisse zu beseitig'n.", sourceObjective = "Tötet 3 verderbte Wächter von Zanchul.", completion = "Das is' übler, als wir dacht'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[47438] = { id = 47438, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine fällige Entscheidung", sourceObjective = "Wählt einen Loa.", progress = "Habt Ihr 'ne Entscheidung getroff'n?", completion = "Ihr habt Eure Wahl getroff'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[47439] = { id = 47439, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gonk, Anführer des Rudels", description = "Ihr findet Gonk in seiner Höhle westlich von hier im Garten der Loa.\n\nDort seht Ihr sicher seine Totems. Wenn Ihr in der Nähe von denen seid, erhöht sich Eure Geschwindigkeit.\n\nIch werd solange weiter diesen Tempel von den Ketzern säubern.\n\nUn' benehmt Euch in Gegenwart des Loas, wenn er Euch nich' die Kehle rausreiß'n soll.", sourceObjective = "Geht mit Gonk einen Handel ein.", completion = "Oh, sehr gut. Er hat Euch also nich' die Kehle rausgeriss'n. 'n gutes Zeichen. Kommt, lasst uns allen zeigen, wen Ihr gewählt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[47440] = { id = 47440, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pa'ku, Herrin der Winde", description = "Kommt, reitet auf Schwingenfürst Ata un' lasst uns Pa'ku aufsuch'n.\n\nUn' benehmt Euch in Gegenwart des Loas. Pa'ku hat schon Anhänger, die sie nich' leiden konnte, aus sehr großer Höhe auf sehr harte Felsen fall'n lass'n.", sourceObjective = "Geht mit Pa'ku einen Handel ein.", completion = "Oh, sehr gut. Sie hat Euch also nich' fall'n lass'n. Ein gutes Zeichen. Kommt, lasst uns allen Eure Wahl bekannt geb'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[47441] = { id = 47441, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nervige Schädlinge", description = "Lasst mich rat'n, die Saurid'n ham Euch also auch was gestohl'n, hm? Also, ich hab keine Zeit, nach allen Kleinigkeiten zu such'n, die diese Wadenbeißer sich krall'n.\n\nWollt Ihr Euch etwas Geld verdien'? Dann helft mir, ein paar von den Schnappern zu töt'n.\n\nUn' wenn nich', dann lasst mich in Ruh.", sourceObjective = "Tötet 8 diebische Schnapper auf dem Zocalo.", completion = "Ein Dieb, der von Dieben stehl'n will?", sourceObjectiveStatus = "unverified-source-field" }
quests[47442] = { id = 47442, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fluch von Jani", description = "<Dieb und Mörder/Diebin und Mörderin>, hört mich an. Ihr steht vor dem Patron der Sammler, dem Fürst'n der Diebe, dem Gott des Mülls, dem Herrscher über Gesindel un' dem Wahrer der Geheimnisse.\n\nIhr steht vor mir in einem Gewand, so kostbar wie das Gold mehrerer Königreiche, un' mit Waffen, die mehr kost'n, als selbst meine treuesten und angesehensten Anhänger je verdien'n werd'n.\n\nScheint mir 'n guter Zeitpunkt, Euch 'ne Lektion zu erteil'n. Jetzt könnt Ihr in all Eurer Macht un' Pracht erfahren, wie's is', im Müll wühl'n zu müssen.", sourceObjective = "Überlebt die Prüfung des Jani.", completion = "Haha, gut gemacht, reicher Fremder. Haltet in diesem Land die Augen off'n. Könnt passier'n, dass Euch eins meiner Kinder auf 'nen interessanten Ort hinweist.", sourceObjectiveStatus = "unverified-source-field" }
quests[47444] = { id = 47444, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vindictive Combatant's Leather Armor" }
quests[47445] = { id = 47445, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Rat der Zanchuli", description = "Ihr da, Stimme der Horde.\n\nMeine Spione ham mir von finster'n Ketzerei'n berichtet, die sich in unsrem heiligen Tempel von Zanchul abspiel'n soll'n.\n\nDer König hat Loti un' Raal losgeschickt, damit sie die Lage dort klär'n, aber die zwei Streithähne von Ratsmitgliedern könn' gegen ihre eignen Anhänger anscheinend keine Härte zeig'n.\n\nWir bräucht'n also jemand mit der richtig'n... neutral'n Härte.\n\nTrefft Euch unten am Zocalo mit Kriegsdruidin Loti un' lasst Euch von ihr den Rest erklär'n.", sourceObjective = "Sprecht mit Kriegsdruidin Loti auf dem Zocalo.", completion = "Willkommen auf'n Stufen von Zanchul, {name}. Gleich betretet Ihr heilig'n Boden.", sourceObjectiveStatus = "unverified-source-field" }
