quests[47473] = { id = 47473, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einschätzung des Gegners", description = "Turalyon hofft zweifelsohne auf bessere Neuigkeiten, doch leider kann ich diese nicht bieten. Ein jetziger Versuch, ins Herz der Legion selbst zu dringen, würde uns alles nehmen.\n\nEs muss einen anderen Weg geben. Ich kenne ihn noch nicht, doch ich werde ihn finden.\n\nWir sollten Turalyon lieber nicht warten lassen. Wir müssen voranschreiten.", sourceObjective = "Sprecht mit Turalyon.", completion = "<Turalyon hört mit finsterer Miene zu.>", sourceObjectiveStatus = "unverified-source-field" }
quests[47485] = { id = 47485, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Handelskompanie Aschenwind", description = "Diese Aschenwindschläger laufen mit einem neuen Pulver herum, mit dem sie eine Galeone einfach so in Stücke schießen können. Und das Militär weiß nichts darüber.\n\nWir müssen herausfinden, wie viel sie von dem Pulver haben und wohin es geliefert wird.\n\nEin alter Kumpel von mir steuert die Fähre unten an der Aschenwindgießerei. Vielleicht weiß er was.\n\nIhr könnt die Fähre vom Handelswindmarkt zum Osthafen nehmen. Wenn Ihr da seid, sucht nach einem Mann namens Cassens. Sagt ihm, Ihr kommt von mir. Er schuldet mir noch einen Gefallen.", sourceObjective = "Sprecht mit Cassens am Osthafen. Nehmt die Fähre von Willi Meinhold am Handelswindmarkt.", completion = "Häh? Was wollt Ihr?", sourceObjectiveStatus = "unverified-source-field" }
quests[47486] = { id = 47486, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verdächtige Lieferungen", description = "Normalerweise würde ich Euch nichts sagen... aber für Carsten mache ich eine Ausnahme.\n\nAschenwind hat da was Großes am Laufen.\n\nSie lassen da rund um die Uhr Leute arbeiten. Sie haben sogar ein paar Muskelpakete abgestellt, um sie alle zu... \"motivieren\".\n\nIch habe keine Ahnung, was die da machen, aber ich weiß, dass es von hier nicht nach Boralus geht.\n\nWäre ich dumm genug, da drinnen herumzuschnüffeln, würde ich mir die Waren selbst ansehen. Ich würde nachsehen, ob sie Versandetiketten haben.\n\nAber weil ich nicht so dumm bin, müsst Ihr das tun.", sourceObjective = "Untersucht 5 markierte Waren in der Aschenwindgießerei.", completion = "Klingt, als würden sie das Zeug tonnenweise herstellen und alles geheim halten.\n\nDas ist übel.", sourceObjectiveStatus = "unverified-source-field" }
quests[47487] = { id = 47487, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arbeitskampf", description = "Aschenwind & Co. nimmt seine Leute so hart ran, dass sie sogar streiken wollten! \n\nUm dem einen Riegel vorzuschieben, haben sie ein paar Schläger angeheuert, die die Leute wieder zur Arbeit geprügelt haben. \n\nIch hab gehört, diese Brutalos hätten sogar ein paar Jungs erschossen, die ihren Posten verlassen wollten.\n\nWas meint Ihr, wollt Ihr denen nicht mal zeigen, wie schön so eine brutale Behandlung ist, solange Ihr da drinnen seid?", sourceObjective = "Tötet 10 Betriebswachposten, Betriebsvollstrecker oder Betriebsfüsiliere.", completion = "Niemand will unter der Knute von solchen Leuten stehen. Keiner wird sie vermissen.", sourceObjectiveStatus = "unverified-source-field" }
quests[47488] = { id = 47488, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kleine Knechte", description = "<Schnief>\n\nSie haben gesagt, sie haben Essen für uns. Und dass wir nicht frieren müssen.\n\n<Olivia wischt sich die Nase am Ärmel ihres Mantels ab.>\n\nAber sie waren gemein! Und es war wirklich harte Arbeit. Und als wir uns ausruhen wollten, haben sie uns angeschrien!\n\n<Schnief>\n\nIch konnte weglaufen, aber die anderen sind noch dort.", sourceObjective = "Befreit 6 schuftende Straßenkinder aus der Aschenwindgießerei.", completion = "Auch ohne unter der Fuchtel von Aschenwind zu stehen, haben es diese Kinder schon schwer genug. Danke, dass Ihr sie da herausgeholt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[47489] = { id = 47489, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verladen und verschickt", description = "<Finn zieht den Kragen hoch, um sein Gesicht zu verbergen, und flüstert Euch zu.>\n\nSeht Ihr das Schiff da? Ich kenne es.\n\nAlso, die Kapitänin und ich sind uns... mal begegnet.\n\nEs ist ein Schmugglerschiff. Da sind mit Sicherheit unsere illegalen Waffen drauf. Darauf würde ich meinen Mantel wetten... und ich mag meinen Mantel.\n\nWir müssen herausfinden, wo sie hinwollen...\n\nHabt Ihr Platzangst?", sourceObjective = "Geht als blinder Passagier an Bord der \"Tugendhaften Maid\".", completion = "Alles in Ordnung mit Euch? Ich fürchte, Euer Schiff ist weg.\n\nAber irgendwie hab ich das Gefühl, dass Ihr nicht wirklich Teil der Mannschaft wart, oder irre ich mich? Haha!", sourceObjectiveStatus = "unverified-source-field" }
quests[47491] = { id = 47491, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überreste der Verdammten", description = "Seit die Geister dies'n \"G'huun\" anruf'n, is' mein Tempel mit der unerträglich'n Verderbnis der Untot'n überzog'n.\n\nDie Untot'n sind zwar Monstrosität'n, aber die Blutsteine, die sie erzeug'n, sind richtig mächtig und könnt'n für Bwonsamdi noch nützlich werd'n.\n\nWenn Ihr mir zeig'n wollt, wie es so um Eure Inbrunst bestellt is', dann säubert meinen Tempel von diesem Dreck un' bringt mir ihre Blutsteine.", sourceObjective = "Sammelt 6 verwesende Blutsteine für Bwonsamdi.", progress = "Habt Ihr meine Blutsteine?", completion = "Ja, damit kann ich was anfang'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[47493] = { id = 47493, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein einsamer Geist", description = "Der Geist von 'nem Kind namens Keula huscht auf'm Tempelgelände rum. Ihre Mutta hat mir das Kind vor 'ner Ewigkeit überlass'n. Sie hat gedacht, dass so 'n großes Opfer sie vor meinem Ruf bewahr'n könnte und sie nich' auf die Andre Seite muss.\n\nTja, damit hat sie auch nich' ganz unrecht gehabt: Ich hab sie mir ja schließlich noch nich' geholt. Aber sie lag auch falsch: Ihre Tochter entscheidet, wann sie ihre Mutta wiederseh'n will, un' ich glaub', sie hat langsam genug von der Warterei.\n\nSie gehör'n beide in mein Reich.\n\nAlso geht los un' bringt das Kind zur Mutta.", sourceObjective = "Sucht Keula in der Nekropole auf.", completion = "Wer seid'n Ihr? Habt Ihr Mutta geseh'n?", sourceObjectiveStatus = "unverified-source-field" }
quests[47496] = { id = 47496, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Panzerknacker" }
quests[47497] = { id = 47497, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grüßt die Goldhauerbande", description = "Seid gegrüßt, <Reisender/Reisende>, un' willkommen im Goldhauer!\n\nAußer Ihr seid hier, um uns zu töt'n... Dann macht Ihr besser 'ne Fliege.\n\nAnsonsten macht's Euch einfach gemütlich un' genießt die Sauerei!\n\nIch mein natürlich, achtet nich' auf die Sauerei. ESST SIE! Nein, doch nich' ess'n. Ignoriert sie!\n\n<Rhan'ka wendet sich dem Schädel mit der Augenklappe zu und schreit ihn heftig in der Sprache der Zandalari an.>\n\nHa, ignoriert den einfach. Hier im Goldhauer sin' alle Verbannten willkommen. Das is' nämlich das einzige Luxusgasthaus hier in dies'n unwirtlich'n Dünen.\n\nKommt, ich will Euch ma' das Personal vorstell'n.", sourceObjective = "Lernt das Personal des Goldhauers kennen.", completion = "Die Hälfte von dem, was die Trolle da faseln, könnt Ihr einfach ignorier'n. Die meinen das nich' so.", sourceObjectiveStatus = "unverified-source-field" }
quests[47498] = { id = 47498, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rhan'kas verschollener Freund", description = "Wenn Ihr zum Totmannpass raufgeht, grüßt doch ma' bitte Zulsan von mir.\n\nDer is' mein bester Kumpel, auch wenn er mir die meiste Zeit am liebst'n aus'm Weg geht. Ha!\n\nAber im Ernst... Der is' jetz' schon seit Tag'n da oben auf den Klipp'n. Falls Ihr ihn findet, überzeugt ihn doch, wieder ins Gasthaus zu komm'. Er muss nämlich unser Frühstücksbuffet wieder auffüll'n.\n\nAch, un' noch 'ne ganz andre Frage, die rein gar nix damit zu tun hat, dass Ihr Zulsan nich' find'n könnt un' ich ihn irgendwie ersetz'n muss: Wie breit is'n Euer Kopf?", sourceObjective = "Findet Zulsan am Totmannpass.", progress = "Habt Ihr Zulsan schon gefund'n?", completion = "Den Geistern sei Dank, dass Ihr Zulsan gefund'n habt. Die Sandwütertrolle ham den Rest der Bande entführt!", sourceObjectiveStatus = "unverified-source-field" }
quests[47499] = { id = 47499, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die grinsenden Götzen", description = "Vor dem Fluch war'n wir 'ne treue Mannschaft von 'nem guten Käpt'n. Aber der Fluch hat Piratenkönig Zem'lan grausam und herrschsüchtig gemacht.\n\nJetzt behandelt er uns wie Sklaven un' nich' wie seine Mannschaft. Er zwingt uns, für sein' Vorteil zu kämpf'n, un' teilt die Schätze nich' mehr mit uns. Un' wenn wir was sag'n, gibt's gleich Strafe.\n\nAlso, wir vier sin' jetzt nich' mehr seine Sklaven.\n\nEin paar von der Mannschaft ham noch diese Götzen, mit den' uns Zem'lan verflucht hat. Tötet die un' nehmt ihnen die Götzen ab. Ich will seh'n, ob man die zerbrech'n kann. Würd mir Spaß bring'n.", sourceObjective = "Sammelt den Götzen der Bindung, den Götzen der Unsterblichkeit und den Götzen der Opferung.", progress = "Ich hatte gehofft, diese Götzen nie wieder seh'n zu müss'n.", completion = "Das sin' verfluchte un' böse Dinger.", sourceObjectiveStatus = "unverified-source-field" }
quests[47501] = { id = 47501, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drecksarbeit und billiger Fusel", description = "Die Gäste müss'n sich im Goldhauer ihr'n Unterhalt verdien'. Was meint Ihr? Wollt Ihr mir vielleicht helf'n, an einem von unsren Ausflugszielen 'n paar Skorpiden zu erledig'n? Zum Beispiel am wunderschönen Totmannpass?!\n\nNormal müsstet Ihr unser Angebotspaket \"Kriegsfürst\" kauf'n, um da raus zu dürf'n, aber ich werd für Euch diesma' 'ne Ausnahme mach'n.\n\nIch geb Euch sogar noch unser Paket \"Skorpidenkönig\" extra dazu. Damit könnt Ihr Euch jed'n Tag den ganz'n Tag lang Skorpidbluttränke hinter die Binde kipp'n!\n\nDie Sache hat bloß einen Hak'n: Wir ham kein Skorpidblut mehr. Bringt uns welches, un' ich schmeiß uns 'ne Runde.", sourceObjective = "Sammelt 20 Einheiten ätzendes Skorpidblut von Schnapptötern am Totmannpass.", progress = "Meine Skorpidbluttränke sin' bei der Goldhauerbande berühmt!", completion = "Ich pass auf das Blut auf, bis wir zurück zum Gasthaus könn', um die Getränke zu mach'n.\n\nKeine Sorge, ich heb extra was auf für Euch. Ich weiß genau, dass Ihr's kaum erwart'n könnt, einen meiner berühmten Skorpidbluttränke zu schlürf'n!", sourceObjectiveStatus = "unverified-source-field" }
quests[47502] = { id = 47502, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die große Schädelschikane", description = "Nachdem Ihr gegang'n wart, ham 'n paar Schläger der Sandwüter das Gasthaus angegriff'n un' die ganze Goldhauerbande entführt!\n\nWir müss'n die zurückhol'n.\n\nMan'zul hat in Zuldazar eigentlich immer die Pläne für unsre Diebstähle ausgeheckt, aber ich versuch ma', mir was einfall'n zu lass'n, um aus dem Schlamassel wieda rauszukomm'.\n\n<Rhan'ka überlegt eine Weile.>\n\nIch hab's! IHR müsst die alle rett'n!", sourceObjective = "Rettet die entführten Mitglieder der Goldhauerbande aus dem Sandwüterunterschlupf.", progress = "Ohne unsre Bande sin' wir nix.", completion = "Ihr gehört jetz' zu uns, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[47503] = { id = 47503, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gozda'kun der Sklaventreiber", description = "Jetz' reicht's. Die Sandwüter ham im Goldhauer hiermit offiziell Hausverbot!\n\nDie können nich' einfach erwart'n, dass die ungestraft den Laden verwüst'n, das Personal entführ'n un' den Besitzer mit 'ner Auswahl an Obst un' Gemüse veralbern könn'!\n\nWir zeig'n diesen Schlägern, was passiert, wenn sie sich mit der Goldhauerbande anleg'n!\n\nGozda'kun der Sklaventreiber hat bei dem Angriff die anderen Sandwüter rumkommandiert.\n\nZieht den aus'm Verkehr un' lasst 'n paar Sandwüter am Leben, damit die es all'n weitererzähl'n könn'.", sourceObjective = "Tötet Gozda'kun den Sklaventreiber im Sandwüterunterschlupf.", completion = "Das wird die Sandwüter lehr'n, dass mit der Goldhauerbande nich' zu spaß'n is'!", sourceObjectiveStatus = "unverified-source-field" }
quests[47506] = { id = 47506, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE" }
quests[47507] = { id = 47507, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Khazaduum" }
quests[47508] = { id = 47508, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuer frei", description = "Seht, wie diese Fledermäuse den Himmel verdunkeln. Wir müssen Fernwaffenunterstützung leisten, aber wir haben hier schon alle Hände voll zu tun.\n\nOffensichtlich hat die Legion noch nicht alle Artilleriebatterien ausgeschaltet. Wenn Ihr eine davon unter Kontrolle bekommt, könntet Ihr die Reihen dieser fliegenden Feinde etwas... lichten.", sourceObjective = "Begebt Euch in die lichtgeschmiedete Batterie und tötet 30 rasende Seuchenschwingen.", completion = "Wir wurden zwar vom Himmel geholt, aber deswegen überlassen wir ihnen noch lange nicht die Lufthoheit!", sourceObjectiveStatus = "unverified-source-field" }
quests[47509] = { id = 47509, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Terrasse der Auserwählten", description = "Dieser Verrat hat das Herz von Zandalar tief getroffen. Die Hälfte des Rats der Zanchuli und seine Anhänger haben sich auf die Seite Zuls geschlagen... und die seines Blutgotts.\n\nZum Glück ist nicht ganz Zandalar auf der Seite der Verräter.\n\nWir müssen Zuls Kultisten stürzen, bevor sie noch mehr Anhänger rekrutieren können. Und am besten fangen wir damit in Zanchul an.\n\nGeht und seht, ob ihr die Zandalari versammeln könnt, die immer noch treu zu ihrem König stehen.", sourceObjective = "Trefft Euch mit Kaza'jin dem Wellenbinder bei der Terrasse der Auserwählten.", completion = "{name}. Schön, dass Ihr noch nich' tot seid!", sourceObjectiveStatus = "unverified-source-field" }
quests[47512] = { id = 47512, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nazmir", description = "Die Bluttrolle im verfluchten Sumpf von Nazmir drohen ganz Zuldazar zu zerstören.\n\nPrinzessin Talanji bittet die Horde, sie bei einer Expedition zu unterstützen, um die Bluttrolle empfindlich zu treffen und die Bedrohung für Zuldazar so zu beenden.", sourceObjective = "Sprecht mit Prinzessin Talanji.", completion = "Der Sumpf von Nazmir is' zweifellos die größte Gefahr für mein Volk. Ich freu mich, dass Ihr Euch entschloss'n habt, mir zur Seite zu steh'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[47513] = { id = 47513, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vol'dun", description = "General Jakra'zet verabscheut die Horde und treibt ein falsches Spiel. Solange er noch an der Macht ist, wird diese Stadt niemals sicher sein.\n\nWir sind nicht allein mit unseren Vorbehalten. Sprecht mit Prinzessin Talanji, um mehr zu erfahren.", sourceObjective = "Sprecht mit Prinzessin Talanji.", completion = "Jakra'zet stellt für mein Königreich und Eure Horde 'ne ernsthafte Gefahr dar. Es wär keine schlechte Idee, wenn Ihr 'n Auge auf seine Aktivitäten werft.", sourceObjectiveStatus = "unverified-source-field" }
quests[47514] = { id = 47514, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zuldazar", description = "König Rastakhan ist ein uralter Herrscher, dessen Vertrauen sich neue Verbündete erst verdienen müssen. Das gilt auch für uns, wenn wir seine Flotte wollen.\n\nZuldazar ist der Machtsitz des Zandalariimperiums und ein guter Ort, um diese potenziellen Verbündeten für uns zu gewinnen.", sourceObjective = "Sprecht mit Prinzessin Talanji.", completion = "Das Vertrauen meines Vaters is' wirklich nicht einfach zu erlang'n.\n\nGlaubt mir.", sourceObjectiveStatus = "unverified-source-field" }
quests[47518] = { id = 47518, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raal", description = "Crazzak is'n Verräter im Priestergewand, der glaubt, er könnt' unsrem Loa wehtun, wenn er uns bloß lang genug foltert.\n\nDie ham sogar meinen Mann Raal auf'n Gipfel von Zanchul geschleppt. Normalerweise könnt'n sie den gern ham, aber die woll'n seine Verbindung zu Pa'ku benutz'n, um den Loa zu schwäch'n.\n\nUn' das darf nich' sein. Also, geh'n wir rauf zum Gipfel von Zanchul un' rett'n wir meinen nutzlos'n Mann.", sourceObjective = "Tötet Crazzak und befreit Hexfürst Raal.", progress = "Das is'n Problem!", completion = "Oje... Musstet Ihr Loti unbedingt mitbring'n? Das wird die mir noch ewig unter die Nase reib'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[47520] = { id = 47520, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wände haben Ohren", description = "Yazma, die Herrin der Spione.\n\nPah! 'ne Verräterin, die auf Krabbelviecher steht. Die hat sich auf die Seite von Zul geschlag'n un' benutzt die Kinder von ihrem Loa Shadra, um jeden unsrer Schritte zu verfolg'n.\n\nWir müss'n alle Spinnen töt'n, die wir seh'n, sonst weiß diese Verräterin Yazma über alles Bescheid, was wir mach'n.", sourceObjective = "Tötet 8 Spinnen in Zanchul.", progress = "Sin' sie tot?", completion = "Gut gemacht. Das sollte Yazma blend'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[47521] = { id = 47521, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mitternacht im Garten der Loa", description = "Yazma un' ihr Trollhandlanger Vol'kaal ham den Großteil ihrer Kämpfer zum Garten der Loa zurückgezog'n. \n\nIrgendwas Übles is' im Gange, das spür ich tief in mir. Pa'ku is' in Gefahr, genau wie die andren Loa, die dort Anhänger ham.\n\nKommt, flieg'n wir da hin un' mach'n wir dem ketzerisch'n Treib'n 'n Ende.", sourceObjective = "Fliegt mit Hexfürst Raal zum Garten der Loa.", completion = "Von hier aus könn' wir zum Gegenschlag auf unsre Feinde aushol'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[47522] = { id = 47522, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Jäger", description = "Gonk is' in Gefahr. Ich hör seinen Ruf.\n\nMein Loa hat mir schon so oft das Leben gerettet, da is' es jetz' echt ma' an der Zeit, dass ich den Gefall'n erwider.\n\nKommt mit mir zur Höhle von Gonk im Westen vom Garten der Loa. Da werd'n wir jetz' nämlich 'nen Gott rett'n.", sourceObjective = "Rettet Gonk.", completion = "Die wollen uns töten und versuchen, uns zu brechen.\n\nAber damit haben sie lediglich erreicht, dass wir alle gemeinsam die größte Jagd veranstalten werden, die die Zandalari je gesehen haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[47523] = { id = 47523, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Störung entdeckt: Schwarzer Tempel", description = "{name}, genau zur rechten Zeit, wie immer.\n\nAls Erstes die gute Nachricht, denn sie findet zur selben Zeit auch für mich statt. Dank der verschiedenen Zeitverzerrungsobjekte aus Vergangenheit und Zukunft, die Ihr entdeckt habt, haben wir herausfinden können, wie man feststellt, dass ein neues davon aufgetaucht ist. \n\nDie schlechte Nachricht ist, dass wir jetzt wissen, dass unsere Technik funktioniert, weil sich im Schwarzen Tempel etwas verändert hat. Und es richtet bereits Schaden in der Zeitlandschaft an! Ihr müsst unbedingt darauf achten, dass der schicksalsträchtige Schlachtzug genauso verläuft wie zuvor und Ihr die Quelle dieser Störung ausschaltet.", sourceObjective = "Durchlebt noch einmal den Angriff auf den Schwarzen Tempel.", progress = "Ihr müsst unbedingt darauf achten, dass der Schlachtzug auf den Tempel genauso verläuft wie zuvor. Ein einziger Extraschlag eines Libellenflügels könnte bedeuten, dass Ihr Illidan tatsächlich tötet! Und dann hätten wir ein großes Problem!", completion = "Was ist das, {name}?\n\n\n\n\n\nDas sind die Pläne für den Schlachtzug auf Mardum. Waren wir zu spät?\n\nUnd noch seltsamer ist, dass dieser Plan besser als das Original zu sein scheint! Das kann nicht das Werk der Legion sein. Illidan hätte ganz sicher jegliche dämonische Manipulation aufgedeckt. Wenn also die Legion nicht dahintersteckt, wer dann?", sourceObjectiveStatus = "unverified-source-field" }
quests[47525] = { id = 47525, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Verborgenen bleiben", description = "Da braut sich was zusamm', Mann. Die Bluttrolle sin' in Bewegung! Sie ham in der Nähe 'n großes Lager aufgebaut un' schick'n 'nen kleinen Trupp zur Insel im Süden.\n\nWenn die uns entdeck'n, bevor wir 'ne Verteidigung ham, is' alles vorbei! Wir müssen schau'n, was die vorham, un' sie loswerd'n.\n\nAm besten erkund'n wir die Insel im Süden. Kommt Ihr mit? Ich bin bereit, loszuzieh'n.", sourceObjective = "Untersucht die Froschmarschen.", completion = "Ich kann nich' mehr kämpfen. Die Bluttrolle haben's auf Krag'wa abgesehen. Sie werd'n ihn an ihren Blutgott verfüttern!", sourceObjectiveStatus = "unverified-source-field" }
quests[47526] = { id = 47526, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwere Geschütze auffahren", description = "Das Urteil des Lichts verfügt über eine Sicherheitsvorrichtung, damit es nicht in feindliche Hände fällt. Wir können den Rückholmechanismus auslösen und es zu einem Schiff zurückteleportieren.\n\nDa die Xenedar außer Gefecht ist, sollte die Waffe zu Eurem Schiff zurückgeholt werden. Ihr könntet ihre Feuerkraft gut brauchen.\n\nAber dieser Vorgang dauert eine Weile und wird wohl die Aufmerksamkeit der Legion auf Euch ziehen. Passt also gut auf.", sourceObjective = "Findet und sichert das Urteil des Lichts.", completion = "<Das Schaltpult pulsiert nun in sanftem goldenen Schein. Laut Romuul sollte das Geschütz durch die Aktivierung zur Vindikaar teleportiert werden.>", sourceObjectiveStatus = "unverified-source-field" }
quests[47527] = { id = 47527, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ketzerische Rituale" }
quests[47528] = { id = 47528, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herrin der Lügen", description = "Wenn Ihr mit dies'n Loa für Bauern fertig seid, könnt Ihr mir ja vielleicht mit meiner eignen Loa Shadra helf'n.\n\nMeine \"Hohepriesterin\" Yazma steckt hinter all dem. Wenn die ihre Scherg'n anstift'n sollte, andere Loa zu töt'n, dann wird sie auch versuch'n, meine eigne Loa zu opfern.\n\nShadras Schrein is' an der nordwestlich'n Seite vom Garten der Loa. Ihr müsst verhindern, dass sie die Herrin der Spione tötet.", sourceObjective = "Besiegt Yazma und Vol'kaal im Garten der Loa.", completion = "Shadra is... verschlungen word'n? So 'ne Ketzerei soll zwar in Zul'Drak schon passiert sein, aber dass es das in Zuldazar geb'n kann...", sourceObjectiveStatus = "unverified-source-field" }
quests[47529] = { id = 47529, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Übernatürliche Unterstützung", description = "Die Loa können ihren Anhängern mächtige Gaben verleihen. Diese Unterstützung kann für uns den Unterschied zwischen Sieg oder Niederlage in dieser Gegend bedeuten.\n\nÜberlegt Euch mit Bedacht, welchen der beiden Ihr um seinen Segen bitten möchtet. Loa unterstützen niemanden, der aktuell einem anderen Loa verpflichtet ist.", sourceObjective = "Wählt, von welchem Loa Ihr einen Segen erhalten möchtet.", sourceObjectiveStatus = "unverified-source-field" }
quests[47540] = { id = 47540, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Totemische Wiederherstellung", description = "Ich bin genährt und mein Körper ist bereit. Ich kann nun mit meiner alten Macht erfüllt werden. Dann bin ich für eine Weile immun gegen ihre Blutflüche und ihren Kraftentzug.\n\nNutzt die Macht der Glühwürmchen, um meine Macht von den Totems auf mich zu übertragen.\nBald werdet Ihr mich wiederhergestellt sehen. Dann vernichten wir das Heer, das sich jenseits des Flusses darauf vorbereitet, mit Gewalt alles an sich zu reißen, was mir gehört.", sourceObjective = "Aktiviert die Macht der Totems und stellt Krag'wa wieder her.", progress = "Ich hatte gehofft, dieses Ritual wäre niemals nötig.", completion = "Ich fühle mich wieder wie ich selbst. Wie damals, als Hunderte Anhänger mir ihren Glauben schenkten. Meine Macht wird nachlassen, doch die Trolle werden erneut lernen, Krag'wa zu fürchten!", sourceObjectiveStatus = "unverified-source-field" }
quests[47541] = { id = 47541, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die beste Verteidigung", description = "Wenn Ihr uns den Hochexarchen zurückgebracht habt, gehört Ihr tatsächlich zu unseren willkommenen Verbündeten.\n\nVon Leuten wie Euch könnten wir noch mehr brauchen. Seht Ihr, wie die Soldaten dort draußen einen ungleichen Kampf führen? Verteidigt sie und schlachtet die Feinde ab.\n\nDas mögen für einen Priester drastische Worte sein, aber jeder Man'ari weniger bedeutet eine Klinge weniger an unseren Kehlen.\n\nZeigt ihnen, dass das Licht seine Auserwählten schützt und die Ungläubigen verbrennt.\n\nSucht Y'mera auf, sobald Ihr das erledigt habt. Sie hat weniger Truppen und deshalb erhöhten Bedarf an Euren Fähigkeiten.", sourceObjective = "Tötet 20 Angreifer auf den Zertrümmerten Feldern.", completion = "Ihr habt Euch gut geschlagen. Dank Euch scheint das Licht umso heller.", sourceObjectiveStatus = "unverified-source-field" }
quests[47542] = { id = 47542, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Belagerungsmeister Voraan" }
quests[47543] = { id = 47543, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Tag, an dem Chromie stirbt", description = "Oh, {name}! Gerade habe ich an Euch gedacht! Das nennt man zur rechten Zeit am rechten Ort!\n\nIch war dabei, Anomalien der Zeitlinien durchzusehen, da habe ich etwas... Unerwartetes entdeckt. Etwas... nicht gerade Schönes.\n\nIn naher Zukunft werde ich sterben. Sehr unangenehm.\n\nIch wollte gerade vorausspringen, um herauszufinden, warum, wie und durch wen... doch es würde mir leichter fallen, wenn <ein/eine:r> {race} wie Ihr an meiner Seite wäre. Würdet Ihr mich begleiten?", sourceObjective = "Sprecht mit Chromie und reist dann in die Zukunft, um zu erfahren, wie sie stirbt.", progress = "Sicher werde ich einfach in ein Loch fallen oder so. Das wär ja nicht das erste Mal!", completion = "Das lief ja nicht gerade gut, was? Vielleicht beim nächsten Mal.", sourceObjectiveStatus = "unverified-source-field" }
quests[47545] = { id = 47545, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurückspulen", description = "Jetzt wissen wir, wann mich der Angriff erwartet, und haben auch eine Ahnung, woher er kommt. Das ist ein Fortschritt! Jetzt müssen wir nur noch mehr Informationen sammeln und den Angriff verhindern!\n\nLasst es mich wissen, wenn Ihr für einen erneuten Versuch bereit seid.", sourceObjective = "Sprecht erneut mit Chromie, reist dann in die Zukunft und sammelt Informationen von den anderen Botschaftern des Wyrmruhtempels.", completion = "Ich schätze, wir haben eine Menge Hinweise, denen wir nachgehen können.\n\nWow, wer auch immer mich tot sehen will, hat sich echt Gedanken darüber gemacht!", sourceObjectiveStatus = "unverified-source-field" }
quests[47550] = { id = 47550, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die vielen Vorteile des Zeitdrachendaseins", description = "Tja, dummerweise für... den, der so scharf darauf ist, mich ins Nichts zu schicken... bin ich eine recht begabte Meisterin der Zeitlinien! Wir haben den Vorteil, dass wir es wieder versuchen können, und dann wieder und wieder, bis ich nicht mehr tot bin.\n\nWir brauchen mehr als ein paar Sekunden, um diesen Angriff aufzuhalten. Was haltet Ihr von vier Stunden?", sourceObjective = "Sprecht ein drittes Mal mit Chromie, reist in die Zukunft und versucht, sie erneut zu retten.", completion = "Fünfzehn Minuten sind nicht viel Zeit. Wir müssen rasch handeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[47551] = { id = 47551, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lektionen von Feuer und Schmerz" }
quests[47552] = { id = 47552, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herrin Il'thendra" }
quests[47554] = { id = 47554, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abfangen der Legionspläne", description = "Unsere Späherin Skara berichtet in dem Schreiben, dass sie von einer größeren Offensive der Legion erfahren hat. Als sie getötet wurde, muss sie auf der Suche nach zwei codierten Befehlen der Legionstruppen in unserer Nähe gewesen sein, die weitere Details enthalten. Die Legion unterteilt ihre Nachrichten in zwei codierte Teile, damit wir sie nicht entziffern können.\n\nSkara schreibt zudem, dass ihre Partnerin, Brae, eine Codeknackerin, bei dem Versuch umgebracht wurde mit einem Codebuch zu uns zurückzukommen. Nur mit diesem Codebuch kann man die Befehle der Legion entziffern. Ihr müsst unbedingt diese Befehle und das Codebuch finden!", sourceObjective = "Sucht auf dem Schlachtfeld nach Truppen der Legion und tötet sie, um ihnen die rätselhaften Legionsbefehle abzunehmen. Beschafft zudem das Codebuch der Armee des Lichts, um die Befehle zu decodieren.", progress = "Habt Ihr die Befehle und das Codebuch gefunden?", completion = "Skara und Brae haben ihre Leben dafür gegeben, uns diese Informationen und das Codebuch zukommen zu lassen. Wir werden ihre Opfer nicht vergessen.\n\nUnd jetzt lasst uns diese Befehle entziffern, um zu sehen, was die Legion vorhat.", sourceObjectiveStatus = "unverified-source-field" }
quests[47557] = { id = 47557, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwelender Chronosplitter", description = "Dieser Kristallsplitter ist glühend heiß. Die Leerenkreatur, die ihn trug, sah nicht wie ein Flammenträger aus, also wird der Chronosplitter wohl auf andere Art mit Feuer in Verbindung stehen.", sourceObjective = "Bringt den schwelenden Chronosplitter zum Wyrmruhtempel, um ein Zeitportal freizuschalten.", completion = "Auuutsch! Ist der heiß! Was könnte das... Oh ja, das ergibt Sinn.", sourceObjectiveStatus = "unverified-source-field" }
quests[47558] = { id = 47558, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teufelsberührter Chronosplitter", description = "Nieten aus grüner teuflischer Energie verunstalten den Kristallsplitter. Das kann schon passieren, wenn etwas von einem Schreckenslord genutzt wird.", sourceObjective = "Bringt den teufelsberührten Chronosplitter zum Wyrmruhtempel, um ein Zeitportal zu öffnen.", completion = "Ein Chronosplitter sagt Ihr? Ich weiß, was man damit machen muss.", sourceObjectiveStatus = "unverified-source-field" }
quests[47559] = { id = 47559, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glänzender Chronosplitter", description = "Dieser Kristallsplitter weist einen metallischen Glanz auf. Chromies Reaktion weist darauf hin, dass er verwendet werden kann, um eine Verbindung mit einer anderen Zeit und einem anderen Ort herzustellen.", sourceObjective = "Bringt den glänzenden Chronosplitter zum Wyrmruhtempel, um ein Zeitportal zu öffnen.", completion = "Reicht mir diesen Chronosplitter, {name}. Wenn es Euch nichts ausmacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[47560] = { id = 47560, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefrorener Chronosplitter", description = "Dieser Kristallsplitter ist von einer dünnen eisigen Schicht Permafrost bedeckt. Er riecht deutlich nach Lich.", sourceObjective = "Bringt den gefrorenen Chronosplitter zum Wyrmruhtempel, um ein Zeitportal zu öffnen.", completion = "Ich hasse es, wenn sie so frostig werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[47561] = { id = 47561, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blasenmaul" }
quests[47563] = { id = 47563, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geister der Gefallenen" }
quests[47564] = { id = 47564, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Büffet aufstocken", sourceObjective = "Sammelt 10 Pfiffblütenschleckfrüchte.", progress = "Das Büffet wird 'ne Katastrophe, wenn wir nich' was von dies'm Obst krieg'n!", completion = "Frühstück is' fertig!", sourceObjectiveStatus = "unverified-source-field" }
quests[47566] = { id = 47566, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gar'zoth" }
quests[47570] = { id = 47570, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheime Vorhaben", description = "Ich verstehe nicht, warum die Naga ein kleines Fischerdorf angreifen sollten.\n\nWarum verschwenden sie ihre Zeit mit unserem unbedeutenden Stamm? Die Naga streben nach Macht und wir haben keine. Das ergibt keinen Sinn!\n\nSie müssen hinter etwas ganz anderem her sein...\n\nGeht zur Finsterwaldbank und versucht, ihre Pläne aufzudecken. Was die Naga auch suchen... Es muss etwas sehr Mächtiges sein.\n\nVielleicht können wir es vor ihnen finden und gegen sie einsetzen!", sourceObjective = "Findet die Invasionspläne der Naga.", progress = "Habt Ihr ihre Pläne aufdecken können?", completion = "Diesen Invasionsplänen zufolge suchen die Naga nach einem uralten Relikt von außergewöhnlicher Macht, das der Ring der Gezeiten genannt wird. Offenbar ging er vor Hunderten von Jahren in einer Schlacht nicht weit von hier verloren...", sourceObjectiveStatus = "unverified-source-field" }
quests[47571] = { id = 47571, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Weisheit des Ältesten", description = "Die Naga suchen nach einem machtvollen Artefakt, dem Ring der Gezeiten.\n\nDen Invasionsplänen zufolge ging er vor langer Zeit in einer Schlacht gegen Eraka no Kimbul, den großen Tigerloa, verloren.\n\nDer Tempel von Eraka no Kimbul liegt nicht weit von hier im Norden. Wenn der Loa damals stark genug war, die Naga zu besiegen, kann er es vielleicht noch einmal tun!\n\nWir müssen dem Stamm berichten, was wir erfahren haben!\n\nBringt die Invasionspläne zum Ältesten Kuppaka. Er ist das älteste und weiseste Mitglied unseres Stammes. Er wird wissen, was zu tun ist.", sourceObjective = "Übergebt die Invasionspläne dem Ältesten Kuppaka.", progress = "Der Älteste Kuppaka wird wissen, was zu tun ist.", completion = "Der Tempel ist nicht weit weg, aber er liegt in Trümmern... und ist verlassen und von Pflanzen überwuchert.", sourceObjectiveStatus = "unverified-source-field" }
quests[47573] = { id = 47573, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dschungelnetzbefall", description = "Die Tempelmauern könnten uns guten Schutz gegen die Naga bieten, aber der Tempel steckt voller Dschungelspinnen.\n\nBevor der Stamm dort Zuflucht suchen kann, müssen wir zuerst diesen Befall beseitigen.\n\nBegebt Euch in den unteren Teil der Ruinen und vernichtet dort die ganze Spinnenbrut.", sourceObjective = "Tötet 6 Dschungelnetzkriecher und 30 Dschungelnetzjunge.", completion = "Da die Spinnenplage jetzt beseitigt ist, können wir den Rest des Stammes sicher zum Tempel führen. Ich danke Euch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[47574] = { id = 47574, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Total versponnen", description = "Die unteren Ruinen des Tempels sind durchzogen von dicken Spinnweben und Spinneneibeuteln.\n\nEinige unserer Stammesbrüder sind in die unteren Ruinen hinabgestiegen, um die Spinnen zu dezimieren, aber sie sind noch nicht zurückgekommen.\n\nIch mache mir Sorgen um sie.\n\nBitte geht in die unteren Ruinen und befreit unsere Brüder, bevor es zu spät ist.", sourceObjective = "Befreit 8 Stammesmitglieder der Tortaka.", completion = "Danke, dass Ihr unsere gefangenen Stammesbrüder gerettet habt. In Zukunft werden wir vorsichtiger sein, wenn wir uns um eine Spinnenplage kümmern.", sourceObjectiveStatus = "unverified-source-field" }
quests[47576] = { id = 47576, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zorn des Tigers", description = "Ich werde den Tortaka meinen Schutz gewähren. In diesem Moment erhebt sich eine Armee der Naga aus den Tiefen und plant, meinen Tempel anzugreifen.\n\nDie Naga haben ihre letzte verlorene Schlacht wohl sehr schnell vergessen!\n\nSie wollen sich den Ring der Gezeiten zurückholen, ein mächtiges Artefakt, das ich einst als Trophäe mitnahm, nachdem ich Azsharas alten Champion Mepjila besiegt hatte.\n\nIch werde Euch als meinen Avatar auf das Schlachtfeld schicken, um die Naga mit fürchterlicher Macht zu vernichten. Sie haben vergessen, was passiert, wenn man meine Anhänger bedroht.\n\nLasst es sie spüren.", sourceObjective = "Schlagt die Nagainvasion zurück.", completion = "Ihr habt Euch tapfer gegen die Naga geschlagen und meinen Tempel verteidigt. Von diesem Tage an seid Ihr ein geehrter Gast in meinem Tempel.", sourceObjectiveStatus = "unverified-source-field" }
quests[47577] = { id = 47577, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sie kamen aus dem Meer", description = "Ihr könnt Euren müden Beine in unserem Lager Ruhe gönnen, aber viel mehr können wir Euch leider nicht anbieten.\n\nDie Naga haben uns aus unserem Dorf am Meer vertrieben. Jetzt können wir weder fischen noch Krabben jagen. Ich fürchte, dass wir nicht mehr lange überleben werden, wenn wir unsere Lagune nicht zurückbekommen.\n\nDie Lagune zurückzuerobern wird aber nicht reichen, befürchte ich. Wir müssen herausfinden, warum die Naga uns angegriffen haben. Wonach suchen sie bloß?\n\nNehmt diese uralte Schriftrolle und beschwört damit die Geister der Naga.\n\nSolange sie unter dem Einfluss dieses Zauberspruchs stehen, werden sie nur die Wahrheit sagen.", sourceObjective = "Befragt 8 Nagageister.", completion = "Habt Dank für Eure Mühen. Die Finsterwaldbank ist jetzt wieder viel sicherer. Aber ich fürchte, dass die Naga mit Verstärkung zurückkehren werden, um nach dem Ring der Gezeiten zu suchen.\n\nWir müssen für dieses Problem eine dauerhaftere Lösung finden...", sourceObjectiveStatus = "unverified-source-field" }
quests[47578] = { id = 47578, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mal des Loas", description = "{name}, Ihr habt Euch meines Segens als würdig erwiesen.\n\nWenn Ihr mich nun als Loa erwählt, könnt Ihr meine Macht nutzen, wann immer Ihr sie braucht.\n\nHaltet Zwiesprache an meinem Schrein, sobald Ihr Euch entschieden habt.\n\nWisset, dass egal wie Ihr Euch auch entscheiden mögt, Ihr in diesen Mauern immer ein willkommener Gast sein werdet.", sourceObjective = "Haltet Zwiesprache an Kimbuls Schrein.", progress = "Ich erteile meinen Anhängern meinen Segen.", completion = "Ihr habt also Eure Wahl getroffen.\n\nFalls Ihr Euch eines Tages anders entscheiden solltet, könnt Ihr jederzeit am Schrein eines beliebigen Loas Zwiesprache halten und seinen Segen erhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[47580] = { id = 47580, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Fluch der Mepjila", description = "Vor Hunderten von Jahren griff die Seehexe Mepjila mit einer Armee von Nagaeindringlingen meinen Tempel an.\n\nMeine Anhänger kämpften tapfer, aber ich kam zu spät, um sie zu retten.\n\nDie Naga bezwang ich mit einem Handstreich, aber als ich Mepjila verschlingen wollte, belegte sie die Geister meiner Anhänger mit einem Fluch, auf dass sie auf ewig in einer Schlacht kämpfen, die sie nicht gewinnen können.\n\nDiese Maske verleiht Euch die Macht, das Geisterreich zu betreten und ihren Alptraum enden zu lassen.\n\nBesiegt den Geist von Mepjila, um den Fluch zu brechen.", sourceObjective = "Besiegt den Geist von Mepjila.", progress = "Ihr müsst den Fluch brechen und die gefangenen Seelen meiner Anhänger befreien.", completion = "Endlich haben meine einstigen Anhänger Frieden gefunden. Ihr habt mir treu gedient, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[47581] = { id = 47581, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Segen von Kimbul", description = "Der Eingang zum Tempel ist mittels einer magischen Barriere versiegelt worden.\n\nLaut meinen Schriftrollen kann diese Barriere nur von jemandem aufgehoben werden, der den Ring der Gezeiten bei sich trägt.\n\nIrgendwo auf dem Tempelgelände gibt es eine Statue, die diesen Ring verleihen kann. Aber die Ruinen wurden von Dschungelspinnen überrannt. Tulu und ich sind nicht stark genug, um den unteren Teil der Tempelruinen selbst zu erkunden.\n\nWenn Ihr den Ring der Gezeiten erhaltet und in den Tempel eindringen könnt, können wir den Naga endlich von Angesicht zu Angesicht gegenübertreten!", sourceObjective = "Beschafft den Ring der Gezeiten.", progress = "Die Statue befindet sich irgendwo in den Tempelruinen.", completion = "Mit dem Ring der Gezeiten solltet Ihr jetzt in den Tempel eindringen und Kontakt zu dem Loa aufnehmen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[47583] = { id = 47583, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dimetrodons müssen sterben!", description = "Es ist ein Wettstreit zwischen Euch, mir und diesen anderen Wilden.\n\nIch finde das... amüsant.\n\nSüdlich von hier findet Ihr einige Dimetrodons. {class}, meine Herausforderung an Euch lautet, mehr von ihnen zu erlegen als ich.\n\nNehmt Ihr an?", sourceObjective = "Tötet 8 giftige Dimetrodons.", completion = "<Es sieht so aus, als ob Fährtenleser Burke auf das, was ihn hier überfallen hat, nicht vorbereitet war. Er ist übersät mit kleinen Einstichen und Wunden.\n\nZu Eurem Glück hat er seine Wertsachen scheinbar in seinem Hut versteckt.>", sourceObjectiveStatus = "unverified-source-field" }
quests[47584] = { id = 47584, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Dorn im Auge", description = "Ihr Narren sprecht von der \"Großwildjagd\", als wäre das ein Mysterium. Pah!\n\nNiemand versteht mehr von der Großwildjagd als meine Sippe. Die große Kunst der Großwildjagd wurde bei uns von Generation zu Generation weitergegeben.\n\nIch werde es Euch beweisen.\n\nIch wette, dass es Euch nicht gelingt, mehr als elf der Ankylodonbestien in dieser Region zu erlegen.", sourceObjective = "Tötet 12 Ankylodons im Reservat.", completion = "<Erak scheint einem Pfeilhagel von hinten erlegen zu sein. Verstörenderweise fehlen einige Teile an der noch frischen Leiche. Aber zum Glück befindet sich sein Wetteinsatz noch bei dem Leichnam.>", sourceObjectiveStatus = "unverified-source-field" }
quests[47585] = { id = 47585, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raubtierhaft", description = "<Die Wunde in seinem Rücken könnte von einem Messer stammen.\n\nWie es scheint, schlägt dort draußen nicht nur die Fauna zurück.>", sourceObjective = "Findet 2 weitere Jäger im Reservat.", completion = "Hmmm. Die sin' absichtlich zurückgelass'n word'n. Da wollte wohl wer, dass wir die find'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[47586] = { id = 47586, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagd auf den Jäger", description = "Euer König der Jäger, Nesingwary, würd auch 'ne hübsche Beute abgeb'n. Ich hatt schon dran gedacht, ihn selbst zu jag'n.\n\nAber jetzt is' ihm jemand andres auf der Fährte. Und das is 'n echt gefährlicher Jäger.\n\nWenn Ihr Euren Jägerkönig rett'n wollt, müsst Ihr ihn schnell aufspür'n. Wenn er ein Lager aufgeschlag'n hat, is' es vielleicht schon zu spät. Wer sich mitten auf'n Präsentierteller setzt, braucht sich nicht zu wundern, wenn er ins Gras beißt.\n\nZuletzt is' er glaub ich in Richtung Westen gegang'n...", sourceObjective = "Sucht nach Hemet Nesingwary.", completion = "Ihr hättet nicht kommen sollen.", sourceObjectiveStatus = "unverified-source-field" }
quests[47587] = { id = 47587, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kopfjäger Jo", description = "Er sagte, er würde Euch jagen. Ich bin nicht die Beute, sondern der Köder!\n\nHinter Euch!", sourceObjective = "Tötet Kopfjäger Jo.", progress = "Was für ein gerissenes Biest!", completion = "Ich danke Euch, {class}. Ich werde in Zukuft ein Auge auf Euch haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[47588] = { id = 47588, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "König der Jagd" }
quests[47589] = { id = 47589, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zorn der Gerechtigkeit", description = "Das Bombardement durch die Verwüster hält den Vorstoß unserer Truppen auf. Ich kann uns nur für begrenzte Zeit vor diesem Beschuss schützen.\n\nChampion, Ihr müsst durch ihre Linien brechen und die Barrieren zerstören, welche die Verwüster beschützen.\n\nWenn es Euch gelingt, die Anker, mit denen die Schilde aufrechterhalten werden, zu vernichten, kann ich sie aus der Ferne ausschalten.", sourceObjective = "Schaltet 3 Verwüster der Legion aus.", completion = "Vielleicht haben wir doch noch eine Chance.", sourceObjectiveStatus = "unverified-source-field" }
quests[47591] = { id = 47591, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wollt Ihr 'ne Lampe kaufen?", description = "He da, wollt Ihr 'ne Lampe kaufen? Werdet's nicht bereuen.", sourceObjective = "Kauft Gaunah die dubiose Lampe ab.", progress = "Ich versprech', das werdet Ihr nich' bereuen.", completion = "Seht Ihr, hab doch gesagt, das wär' 'ne gute Idee!", sourceObjectiveStatus = "unverified-source-field" }
quests[47592] = { id = 47592, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glänzend wie ein Diamant", description = "Oh, tut mir leid. Die Lampe könnt 'n bisschen Pflege gebrauchen. Hab ich was für da.", sourceObjective = "Kauft ein zertifiziert biologisches Lampenputzset von Gaunah und säubert damit die schmierige Lampe.", progress = "Bin sicher, das wird's wert sein.", completion = "Uhh, uhh, lasst mal sehen!", sourceObjectiveStatus = "unverified-source-field" }
quests[47593] = { id = 47593, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magische Münzen, sagt Ihr?" }
quests[47594] = { id = 47594, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die nehm' ich, danke!", description = "Die Münz'n hier lösen sich \"puff\" in Luft auf? Das passt ja, wie die Faust auf's Auge. Ich weiß genau, wem ich die stecke.", sourceObjective = "Besorgt 10.000 Münzen der Luft für Gaunah.", progress = "Oh Mann, kann gar nicht erwarten, die zu benutzen. Ich dank Euch.", completion = "Bester Tag aller Zeiten. Den Baron führ' ich so weit hinters Licht, der wird den Weg nicht mehr zurückfinden.", sourceObjectiveStatus = "unverified-source-field" }
quests[47595] = { id = 47595, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brauch' ich nicht, nehm's aber trotzdem", description = "Wenn Ihr noch mehr sammeln wollt, stört das Gaunah kein bisschen. Aber ich brauch da jetzt nich' mehr so viel von, also zahl' ich Euch weniger.", sourceObjective = "Sammelt 10.000 Münzen der Luft für Gaunah.", progress = "Noch eine Ladung? Die Dinger scheinen Euch wirklich zu gefallen.", completion = "Wollt Ihr das sicher tun? Ich hab diese deutlich interessanteren Waren und nächste Woche brauch' ich mehr davon.", sourceObjectiveStatus = "unverified-source-field" }
quests[47596] = { id = 47596, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kein Plan B", description = "Hört mal, ich will ehrlich sein. Unser Mech, der A.M.O.D., war der beste, den wir je gebaut haben. Er war beweglich, hatte Wumms und so einen gibt es kein zweites Mal!\n\nWas ich damit sagen will: Ohne ihn ist unser ganzer Plan ruiniert! Wir müssen ihn bergen und neu aufbauen!\n\nDieser Riesentrampel von einem Meeresriesen hat den A.M.O.D. zerstört und die Teile an der ganzen Küste verstreut. Sucht die Teile, dann versuche ich, ihn wieder zusammenzuschustern.", sourceObjective = "Findet alle Teile des A.M.O.D.", progress = "Habt Ihr die Teile schon?", completion = "Ihr habt offenbar alles... oder zumindest haben wir die wichtigen Teile. Jetzt haben wir eine Menge Reparaturarbeit vor uns.", sourceObjectiveStatus = "unverified-source-field" }
quests[47597] = { id = 47597, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kein Goblin wird zurückgelassen", description = "Mit unserer Mission ist es vorbei, wenn wir uns nicht beeilen!\n\nIch habe ein perfektes Plätzchen für eine neue Basis gefunden. Ihr müsst die Mannschaft retten und zurückbringen, während ich den Standort sichere. Das haben wir tausendmal trainiert. Schickt sie einfach in Richtung des Treffpunkts, die finden den Weg dann schon.\n\nWir haben nicht viel Zeit, also hopp, hopp!", sourceObjective = "Findet und rettet die vermissten Mitglieder des Goblintrupps.", completion = "Der ganze Trupp ist vollständig anwesend. Hervorragende Arbeit!", sourceObjectiveStatus = "unverified-source-field" }
quests[47598] = { id = 47598, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hamstern und hehlen", description = "Unsere Schiffe wurden versenkt und unser A.M.O.D. ist zerstört. Wir haben auf dieser Mission RIESIGE Verluste gemacht und das Bilgewasserkartell bietet für sowas keine Versicherung an. Die Schuldeneintreiber werden uns ins Genick steigen! Wir müssen diese Verluste ausgleichen.\n\nAm Strand wimmelt es von Naga, die Artefakte aus den Ruinen zu bergen versuchen. Wie wär's, wenn wir uns einen Teil dieser Schätze schnappen, um unsere Verluste gutzumachen? Wir finden bestimmt einen Käufer, der sie uns abnimmt.\n\nWir teilen uns den Gewinn 80 zu 20. Klingt doch fair.", sourceObjective = "Sammelt 20 uralte Relikte der Titanen von den Naga am Zertrümmerten Übergang.", progress = "Habt Ihr etwas für mich?", completion = "Sauber abgeräumt! Damit sollte uns das Kartell nicht mehr im Genick sitzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[47599] = { id = 47599, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rache, heiß serviert", description = "Der Chef behält hier vielleicht einen kühlen Kopf, aber wir sollten diesen Naga zeigen, was passiert, wenn man sich mit dem Goblintrupp anlegt. Findet Ihr nicht?\n\nDie Naga schicken ihre Ungetüme, um den Rest unseres Schiffs zu zerstören. Schnappt Ihr Euch doch meinen Raketenwerfer, um ein Exempel zu statuieren. Dann ist gleich klar, wie das hier läuft!", sourceObjective = "Benutzt Tickers Raketenwerfer, um 4 Ungetüme der Faulschuppen zu töten.", completion = "Na bitte! Eine Schweigeminute für die gar nicht so lieben Verstorbenen.\n\nUnnnd... schon vorbei.", sourceObjectiveStatus = "unverified-source-field" }
quests[47601] = { id = 47601, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einsatzbeurteilung", description = "Wir haben den A.M.O.D. wieder zusammenbekommen. Er ist ein gutes Stück, muss aber optimiert werden. Wir wollen ja nicht, dass wir nachher eine Ladung Schrapnell im Hinterteil haben.\n\nZum Glück für uns gibt es außer dem Riesen, der ihn überhaupt erst zerstört hat, auch noch Nagalager. Die eignen sich hervorragend für Zielübungen.\n\nWir setzen den A.M.O.D. vor dem Gebäude hier ein. Danach könnt Ihr ihn besetzen. Ihr feuert einige Salven ab, während ich seine Kanone anpasse.\n\nDas wird schon alles... oder eben nicht.", sourceObjective = "Verwendet den A.M.O.D., um die Nagalager zu zerstören und Grobathan zu besiegen.", completion = "Hervorragende Arbeit! Der A.M.O.D. braucht noch ein paar geringfügige Anpassungen, aber damit kommen wir schon klar.\n\nAch, und übrigens... gut geschossen!", sourceObjectiveStatus = "unverified-source-field" }
quests[47602] = { id = 47602, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einsatzbereit", description = "Es wird eine Weile dauern, dieses Kanonengestell aufzubauen. Wer hätte gedacht, dass große Teile so schwer zu heben sind?\n\nSchaut Ihr doch in der Zwischenzeit noch mal bei Euren Freunden vorbei. Stellt sicher, dass bei denen alles bereit ist. Ich würde mit dieser Kanone ungern in einen WEITEREN Hinterhalt geraten, nur weil die nicht vorbereitet sind.", sourceObjective = "Reist zum Trübsumpf und sprecht mit Prinzessin Talanji.", completion = "Naga sagt Ihr?\n\nDas klingt nach 'ner echten Krise. Ich bin froh, dass Ihr die Dinge wieder in Ordnung gebracht habt!", sourceObjectiveStatus = "unverified-source-field" }
quests[47603] = { id = 47603, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der geheimnisvolle und famose Al'Abas", description = "Ich sehe Euch, <ärmlicher Sterblicher/ärmliche Sterbliche>! Ich danke Euch für die Pflege meiner Lampe!", sourceObjective = "Sprecht mit Al'Abas.", progress = "Die gesamte Welt krümmt sich im Angesicht ihrer magischen Last. Sie quillt förmlich aus ihren Taschen.", completion = "Ihr könnt sie wirklich nicht sehen? Ich vermag, die Magie in Ihren Taschen zu spüren!", sourceObjectiveStatus = "unverified-source-field" }
quests[47604] = { id = 47604, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Land der Magie", description = "Ich meine, das Problem zu erkennen. Eure jämmerlichen Äuglein sind zu schwach, um die manaerfüllten Kostbarkeiten wahrzunehmen, die diese Elfen im ganzen Land verteilt haben. Sie tragen den Schmuck schon die ganze Zeit, aber Ihr konntet ihn einfach nicht sehen.\n\nIch schlage Euch ein Bündnis vor. Meine Lampe leidet derzeit unter einem peinlichen Mangel an Magie und könnte noch mehr edlere Verzierungen vertragen. Deshalb will ich Euch einen Handel anbieten. Ich durchtrenne diesen sinistren Schleier und Ihr überlasst mir die Beute Eures Diebstahls.", sourceObjective = "Sprecht mit Al'Abas... auf ein Neues.", completion = "Prächtig, einfach prächtig. Dies verheißt eine ergiebige Partnerschaft zu werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[47605] = { id = 47605, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Münzen der Luft", description = "Ich hege größtes Interesse an dem magischen Geschmeide, das in den Taschen der Bewohner dieser Lande zu finden ist. Demgemäß biete ich bei der Beschaffung ebenjener untertänigst meine Dienste an, {name}.\n\nZu meinem Unglück vermag ich nicht, Eure Mühen im hergebrachten Obolus dieser Welt zu vergelten. Was ich offerieren kann, sind Ephemera – Münzen von reinster Luft. \"Besser als nichts\", wie Ihr so schön sagt, nicht?\n\nTragt meine Lampe mit Euch. Verstaut Eure gestohlenen Schätze darin und ich werde sie mit diesen Münzen aufwiegen. Der einstige Besitzer meiner Lampe hat womöglich eine Verwendung dafür.", sourceObjective = "Sprecht abermals mit Al'Abas.", completion = "Ich überantworte meine Lampe Eurer verheißungsvollen Obhut. Möge unsere Partnerschaft ersprießlich sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[47606] = { id = 47606, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treue ist eine Belohnung in sich", description = "Ich biete Euch eine Herausforderung, sterbliches Wesen. Erlangt eintausend meiner Münzen und ich bin zuversichtlich, die seherische Macht meiner Lampe verstärken zu können.", sourceObjective = "Erlangt 1000 Münzen der Luft.", progress = "Meine Güte! So rasch?!", completion = "Ja, ja, JA! Seht Ihr die Macht, die meine Lampe ausstrahlt? Ich kann Objekte größter Macht spüren, die bisher selbst meinen mächtigen Augen verborgen blieben.", sourceObjectiveStatus = "unverified-source-field" }
quests[47607] = { id = 47607, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dschinn mit Modesinn", description = "Durch meine noch mächtigere Lampe spüre ich eine viel größere Fülle an kostbarem Geschmeide in den Taschen dieser Elfen und Dämonen. Beglückt mich mit ihrem Besitz!", sourceObjective = "Durchsucht die Taschen der Bewohner der Verheerten Inseln nach seltenen Schätzen.", progress = "Seht an, seht an. Ihr erstaunt und erheitert auch weiterhin, sterbliches Wesen.", completion = "Ihr habt es geschafft! Meine Lampe ist nie heller erstrahlt. Ich werde Euch auch weiterhin Münzen gewähren, doch ich muss einen neuen Nutzen für Eure Magie finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[47608] = { id = 47608, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wenn Ihr es nur sehen könntet" }
quests[47609] = { id = 47609, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wild Gladiator's Chain Armor" }
