quests[47620] = { id = 47620, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lich Lord Plate" }
quests[47621] = { id = 47621, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein wahrer Loafestschmaus", description = "Die Angriffe der Bluttrolle haben bis jetzt nicht aufgehört. Sie haben mich erheblich geschwächt und ich muss wieder zu Kräften kommen. Meine Anhänger haben mir früher Fleisch aus der Umgebung als Opfer dargeboten.\n\nGeht und bringt mir ein ordentliches Festmahl. Dann werde ich wieder stark und wir werden diesen Angriffen ein für alle Mal ein Ende setzen.", sourceObjective = "Tötet in den Oberen Froschmarschen in Nazmir Tiere und nehmt ihr Fleisch.", progress = "Ich hungere.", completion = "<Krag'wa verschlingt das ganze Fleisch in wenigen Happen.> Ja! Ich war so lange hungrig. Je mehr meiner Anhänger starben, desto hungriger wurde ich.\n\nWenn sich uns noch mehr anschließen, wird das Essen vielleicht wieder zu dem Vergnügen, das es einst war.", sourceObjectiveStatus = "unverified-source-field" }
quests[47622] = { id = 47622, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein zauberhaftes Leuchten", description = "Vor langer Zeit, als die Trolle begannen, auf das Flüstern der Dunkelheit zu hören, habe ich einen Teil meiner Macht auf die Totems in meiner Höhle übertragen. Diese Macht brauche ich jetzt.\n\nIn den Sümpfen nördlich von hier gibt es Glühwürmchen. Deren magische Essenz wird mir helfen, die gespeicherte Macht aus den Totems zu ziehen. Sammelt sie und kehrt zu mir zurück. Dann werdet Ihr sehen, wozu ich im vollen Besitz meiner Macht imstande bin.", sourceObjective = "Sammelt wunderschöne Glühwürmchen in den Oberen Froschmarschen.", completion = "Ich hätte das vor langer Zeit tun sollen, als meine Anhänger dahingemetzelt wurden, aber die Bluttrolle waren immer zu stark.\n\nIhr seid unsere letzte und beste Chance, zu überleben.", sourceObjectiveStatus = "unverified-source-field" }
quests[47623] = { id = 47623, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der letzte Hexendoktor von Krag'wa", description = "Ich bin Krag'wa und war einst mächtig. Verfluchte Bluttrolle und ihr dunkler Gott! Sie haben meine Anhänger getötet, bis nur noch Zentimo verblieb, und jetzt ist auch er tot.\n\nIch will Rache an den Bluttrollen nehmen, aber zunächst muss ich meinen letzten Hexendoktor ehren. Da es sonst niemanden gibt, muss ich Euch bitten, das Ritual durchzuführen.\n\nDann können wir über Rache sprechen.", sourceObjective = "Beschafft das Szepter der Wiedergeburt und führt das Ritual von Krag'wa bei Zentimo durch.", progress = "Zentimo muss gewürdigt werden.", completion = "Euer Ritual war gut durchgeführt.\n\nMit Eurer Hilfe werde ich nicht an den Gott der Bluttrolle verfüttert. Stattdessen werde ICH ein Festmahl genießen!", sourceObjectiveStatus = "unverified-source-field" }
quests[47624] = { id = 47624, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vergraben" }
quests[47625] = { id = 47625, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geteiltes Ritual" }
quests[47627] = { id = 47627, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rache", description = "Die Armee des Lichts soll nicht vergeblich gefallen sein.\n\nUnsere Truppen greifen das Hauptlager an, während wir ihre Belagerungswaffe zerstören.\n\nUnd das wird nur der Anfang unserer Vergeltung sein.", sourceObjective = "Zerstört die Belagerungswaffe an der Krone der Zerstörung.", progress = "Solange ihre Waffe eine Bedrohung darstellt, sitzen wir hier wie Ungeziefer in der Falle.", completion = "Wir scheinen die Gerissenheit der Legion unterschätzt zu haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[47631] = { id = 47631, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treffen mit der Goldkelch", description = "Ich sag's Euch ehrlich, Mann. Ich hab keine Zeit für Goblins un' ihre Mätzchen.\n\nTrefft Ihr Euch mit ihrem Anführer un' sorgt dafür, dass seine Besatzung un' die Waffe bereit für den Angriff sin'. Die Bluttrolle werd'n Zuldazar überrenn', wenn wir versag'n.\n\nViel Glück, {name}!", sourceObjective = "Sprecht mit Flick am Überwucherten Riff.", completion = "Unsere Mission ist eine Katastrophe, eine einzige Katastrophe!\n\nWir wollten gerade den Anker auswerfen, als die Naga in Scharen über das Schiff hergefallen sind! Es war ein harter Kampf, aber wir hatten die Oberhand... bis aus dem Nichts plötzlich ein Meeresriese aufgetaucht ist. Der hat das Schiff schlimmer gebeutelt als ein Vorarbeiter einen faulen Peon.\n\nKeine Sorge, {name}. Wir werden diesen Plan schon noch retten. Aber zuerst müssen wir die Besatzung versammeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[47638] = { id = 47638, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mächtige Geister", sourceObjective = "Durchlauft das Aufnahmeritual der Goldhauerbande.", completion = "Ihr gehört jetz' zur Goldhauerbande, {name}. Willkommen zu Hause.", sourceObjectiveStatus = "unverified-source-field" }
quests[47641] = { id = 47641, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeichen des Widerstands", sourceObjective = "Sucht nach Zeichen des Widerstands.", completion = "Das muss es sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[47642] = { id = 47642, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seelenkristall", description = "<Die drei Scherben lassen sich nahtlos zu einem großen Kristall verbinden. Sobald sie verbunden sind, erscheint das Abbild eines mächtigen Lichs über dem Kristall.>\n\n<Der Lich spricht:>\n\nHaltet die Rubinschreinwächter in Schach. Ich werde den Angriff unseres Meisters vom Inneren des großen Baums aus selbst ausführen.", sourceObjective = "Findet den Lich, der sich im Baum des Rubindrachenschreins versteckt.", completion = "Hier sollte es sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[47643] = { id = 47643, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weisheit der Urtume", description = "Die drei Urtume haben drei Hinweise hinterlassen:\n\n\"...der große Alptraum...\"\n\n\"...am Wasser...\"\n\n\"...in der Hand des Drachen...\"\n\nVielleicht befindet sich Chromies Angreifer an dem Ort, den die Urtume beschreiben?", sourceObjective = "Findet den Satyr, der sich im Smaragddrachenschrein versteckt.", completion = "Das muss der Ort sein, zu dem die Hinweise der Urtume führen. Er MUSS es einfach sein!\n\nLegen wir los, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[47644] = { id = 47644, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dämonischer Kernstein", description = "<Aus den Tiefen des dämonischen Kernsteins spricht das Abbild eines Schreckenslords unheilvoll:>\n\nJa, Meister. Ich werde mich darum kümmern. Genau zu der Zeit, die Ihr erwählt habt. Der Bronzedrache wird nichts bemerken. Ich brauche nur einen Schuss von der Außenseite des Obsidiandrachenschreins.", sourceObjective = "Findet den Schreckenslord, der sich nahe dem Eingang zur Höhle des Obsidiandrachenschreins versteckt.", completion = "Ich bin keine große Freundin von Schreckenslords, aber ich denke, gemeinsam können wir beide ihn schon bezwingen. Seid Ihr bereit, {name}?", sourceObjectiveStatus = "unverified-source-field" }
quests[47645] = { id = 47645, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schriftrolle des Leerrufers", description = "<Die Teile der Schriftrolle verbinden sich zu einer zerfledderten, aber lesbaren Nachricht:>\n\nDie Zeit ist gekommen. Die Beschwörung wird über dem Azurschrein stattfinden. Die Leere wird den Bronzedrachen verschlingen. Unser Meister hat gesprochen und wir gehorchen.", sourceObjective = "Findet die Leerenkreatur, die sich über dem Azurdrachenschrein versteckt.", completion = "Ich spüre etwas... Schlechtes.", sourceObjectiveStatus = "unverified-source-field" }
quests[47646] = { id = 47646, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angeleint" }
quests[47647] = { id = 47647, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Monster von Zem'lan" }
quests[47652] = { id = 47652, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Lichtmutter", description = "Wir müssen uns vergewissern, ob die Lichtmutter überlebt hat, {name}.\n\nXe'ra wurde geschwächt, als sie ihr Herz nach Azeroth gesandt hat, aber sie ist die erste Naaru. Sie ist das Licht und sie kann nicht vergehen.\n\nBegeben wir uns in die Xenedar und suchen wir nach ihr. So das Licht es will, wird sie zurückkehren und uns abermals führen.", sourceObjective = "Findet Xe'ra in der Xenedar.", progress = "Lichtmutter... Ihr müsst einfach überlebt haben...", completion = "Dem Licht sei Dank! Dies war ein dunkler Tag und viele Leben gingen verloren.\n\nAber die Armee wird überleben und die Prophezeiung der Mutter wird erfüllt.\n\nEs ist alles so, wie es sein sollte.", sourceObjectiveStatus = "unverified-source-field" }
quests[47653] = { id = 47653, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rückkehr des Lichts", description = "Xe'ra ist gerettet! Wir haben damit einen bedeutenden Sieg errungen.\n\nDie Lichtmutter müsste bereits auf der Vindikaar eingetroffen sein. Sie wird sicher mit Euch sprechen wollen. Es gibt so viel zu erklären...\n\nRomuul müsste uns jetzt zurück zum Schiff teleportieren können. Lasst es mich wissen, wenn Ihr bereit seid.", sourceObjective = "Sprecht mit Turalyon, um zur Vindikaar zurückzukehren.", completion = "Die Armee wird überleben und die Prophezeiung der Mutter wird erfüllt.\n\nEs ist alles so, wie es sein sollte.", sourceObjectiveStatus = "unverified-source-field" }
quests[47654] = { id = 47654, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sitz des Triumvirats: Das Wappen des Wissens", description = "Wir haben jetzt alles, was wir brauchen, {name}.\n\nAlleria Windläufer erwartet Euch am Sitz des Triumvirats.\n\nAber geht nicht allein. Ihr benötigt Verbündete, um das Wappen des Wissens zu bergen... und um gegen das anzukommen, was aus L'ura geworden ist.\n\nIch werde die Vindikaar vorbereiten und auf Eure Rückkehr warten. Möge das Licht an diesem düsteren Ort mit Euch sein.", sourceObjective = "Tötet L'ura und bergt das Wappen des Wissens.", progress = "Ich mute Euch eine schwere Bürde zu, {name}. Ich bin sicher, dass Ihr mich nicht enttäuschen werdet.", completion = "Es ist vollbracht. Mein Herz leidet unter L'uras Ende, doch wenigstens hat sie nun ihren Frieden gefunden.\n\nSobald die Krone platziert wurde, wird die Vindikaar gegen den niederträchtigen Angriff der Legion bestehen. Dann wird Antorus fallen!", sourceObjectiveStatus = "unverified-source-field" }
quests[47659] = { id = 47659, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagt den Jäger", description = "Bitte helft uns. Die Froschmarschen werd'n angegriff'n! Mein Meister, der große Loa Krag'wa, beugt sich dem Willen der Bluttrolle und ihres Meisters nich'. Jetzt nehm'n sie seine Macht mit Gewalt! Sie bring'n seine Kinder um und stehl'n die Totems seiner Macht. Sie werd'n Krag'wa sogar opfern, wenn wir diesem Wahnsinn kein Ende setz'n!\n\nHaltet sie auf! Tötet ihren Anführer. Vielleicht hält sie das 'ne Weile auf. Das gibt mir Zeit, 'ne dauerhaftere Lösung zu find'n.", sourceObjective = "Tötet Kriegsmatrone Boatema in der Nähe der Froschmarschen.", completion = "Eure Taten bleiben nicht unbemerkt. Zentimo hat Euch erwähnt, bevor er verschieden ist.\n\nAls ich mich der Verderbnis der Bluttrolle widersetzte, griffen sie an. Jetzt wollen sie mich ihrem Gott opfern.\n\nIch habe keine Anhänger mehr, durch die ich handeln könnte, doch vielleicht helft Ihr mir noch weiter.", sourceObjectiveStatus = "unverified-source-field" }
quests[47660] = { id = 47660, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefallene Götzen", description = "Die Bluttrolle woll'n Krag'wa schwäch'n und ihm seine Macht entzieh'n. Sie klau'n seine Götzen, brech'n sie auf und tun sich an ihrer Magie gütlich.\n\nRettet so viele Götzen wie möglich. Wir werd'n sie brauch'n, um Krag'wa zu stärk'n. Stark genug, um sie ein für alle Mal zurückzuschlag'n.", sourceObjective = "Sammelt Krag'was gestohlene Götzen im Bluttrolllager in den Froschmarschen.", progress = "Meine Götzen?", completion = "Meine Götzen! So viele wurden entwendet oder zerstört. Ich weiß, dass Ihr so viele gerettet habt wie möglich. Aber das wird nicht reichen.\n\nZu viel von ihrer einstigen Macht wurde erschöpft.", sourceObjectiveStatus = "unverified-source-field" }
quests[47663] = { id = 47663, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein rechtzeitiger Ruf aus Shattrath", description = "In diesem Zyklus befindet sich der gleißende Stern in einer eigenartigen Stellung und ruft aus den Himmeln herab. Begebt Euch zur Weisen Vormu in Shattrath und bietet ihr Eure Hilfe an.", sourceObjective = "Trefft Euch mit Vormu in Shattrath.", progress = "Ich kann sehen, dass Ihr die Stärke vieler Verbündeter brauchen werdet, um auf diesem Pfad zu wandeln.", completion = "Oh, ist es schon so weit?", sourceObjectiveStatus = "unverified-source-field" }
quests[47685] = { id = 47685, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herausforderung des Torwächters: Gerissenheit", description = "Archimonde hat große Ansprüche an seine Schüler gestellt. Nur die kreativsten Geister und klügsten Talente waren in der Lage, die Tiefen unserer Magie zu ergründen.\n\nIch erwarte nicht, dass Ihr das versteht.\n\nDer Pfad links führt Euch zu einer Ansammlung von drei Statuen. Mit ihrer Hilfe könnt Ihr das Mal der Gerissenheit erhalten.\n\nUm die Korrektheit der Prüfung zu wahren, darf ich Euch keine weiteren Hinweise geben. Solltet Ihr, was einem Wunder gleichkäme, Erfolg haben, werde ich offiziell Eure... Genialität anerkennen.", sourceObjective = "Sammelt die Fragmente des Scharfsinns, des Intellekts und der Verschlagenheit ein und kombiniert sie zu einem Mal der Gerissenheit.", progress = "Zeigt mir das Mal der Gerissenheit oder lasst mich in Ruhe.", completion = "Oh, Ihr hattet Erfolg.\n\nDas überrascht mich.", sourceObjectiveStatus = "unverified-source-field" }
quests[47686] = { id = 47686, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht ganz so bescheidene Anfänge", description = "Jetzt können wir uns auf die Suche nach der Krone des Triumvirats machen. Wir beginnen mit Archimondes Fragment, dem Siegel des Erwachens.\n\nIm Osten und Norden findet Ihr alles, was von der einst größten Magierschule auf Argus übrig geblieben ist. Dort hat Archimonde seine Meisterschaft des Arkanen erlangt. Ich wüsste keinen anderen Ort, wo er seine Schätze verstecken sollte.\n\nEr wird mit Sicherheit bewacht sein. Wir werden uns von Fareeyas Truppen helfen lassen, um seiner Spur folgen zu können.", sourceObjective = "Trefft Euch mit Erzmagierin Y'mera im Arkankonservatorium.", completion = "Dieser Ort birgt so einige Geheimnisse. Zum Glück kenne ich genug von ihnen, sodass wir loslegen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[47687] = { id = 47687, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herausforderung des Torwächters: Meisterschaft", description = "Archimonde war ein Individuum, das sich dem Streben nach Macht verschrieben hatte. Nur wer dieses Streben mit ihm gemein hatte, durfte auf seine Gunst hoffen.\n\nIhr werdet gegen das antreten, was von den größten Schülern Archimondes übrig ist. Diese drei waren in ihren jeweiligen Disziplinen so mächtig, dass sich das Konservatorium bis heute an sie erinnert.\n\nIhre Echos werden versuchen, Euch zu töten.\n\nWenn Ihr sie alle drei besiegt und unbeschadet bleibt, werde ich Eure Stärke anerkennen.", sourceObjective = "Besiegt Großwesir Jarasum, Erzkonsulin Velara und Hocherwecker Aargon.", completion = "Ich muss zugeben, dass ich beeindruckt bin.", sourceObjectiveStatus = "unverified-source-field" }
quests[47688] = { id = 47688, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Invasive Spezies", description = "Für den Fall, dass ich mich bezüglich der Leitungen geirrt habe, sollten wir nach einer alternativen Energiequelle suchen.\n\nUnd glücklicherweise weiß ich auch, wo wir eine finden können.\n\nDie auf Argus heimischen Panthara sind einzelgängerisch lebende Tiere, aber die Magie der Erwecker scheint sie in großer Zahl hierhergezogen zu haben.\n\nPanthara verschlingen Energie, um zu überleben, und wir können derzeit keine Rücksicht auf das hiesige Ökosystem nehmen.\n\nErlegt sie und versucht, einen Teil der von ihnen aufgenommenen Energie für unsere Zwecke zu nutzen.", sourceObjective = "Sammelt 30 Einheiten teilweise verdautes Arkana.", progress = "Es ist immer gut, einen Plan B zu haben. Habt Ihr gefunden, wonach wir suchen?", completion = "Ich hatte nicht erwartet, dass das Endprodukt so... klebrig sein würde.\n\n<Y'mera wischt sich die Hände an ihrem Gewand ab.>\n\nDas sollte funktionieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[47689] = { id = 47689, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herausforderung des Torwächters: Zuverlässigkeit", description = "Mein Meister, Archimonde, war dafür bekannt, dass er keinerlei Nachsicht mit den Zaudernden kannte.\n\nVielmehr lehrte er, indem er Frustration mit Frustration bestrafte und auf Strafen noch mehr Strafen folgen ließ. Wer unter ihm erfolgreich sein wollte, musste absolute Überzeugung an den Tag legen.\n\nAuf der anderen Seite des Konservatoriums findet Ihr ein großes Gebäude. In seinem Inneren müsst Ihr alle Herausforderungen bestehen, mit denen Ihr konfrontiert werdet.\n\nWenn Ihr es unversehrt herausschafft, werde ich zulassen müssen, dass Ihr weitermacht.", sourceObjective = "Besteht die Prüfung der Zuverlässigkeit.", completion = "Wenn Ihr so lange überleben konntet, seid Ihr es vielleicht wert, die Geheimnisse des Konservatoriums kennenzulernen.", sourceObjectiveStatus = "unverified-source-field" }
quests[47690] = { id = 47690, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Nachlass des Entweihers", description = "Ihr scheint Euch nicht so leicht beirren zu lassen. Nun denn.\n\nEure Fertigkeiten qualifizieren Euch dazu, weiter nach dem Siegel zu streben. Aber Ihr habt lediglich meine Erlaubnis, weiterzumachen. Ich verspreche Euch keinen Erfolg.\n\nDie größte Herausforderung liegt noch vor Euch.\n\nIhr müsst Euch in das Prätorium begeben und gegen Archimonde höchstpersönlich antreten. Nur wenn Ihr den Meister des Konservatoriums besiegen könnt, seid Ihr des Siegels würdig.\n\nDiese Herausforderung haben nur wenige je bestanden. Ich hoffe, dass er Euch nicht zu sehr verunstaltet.", sourceObjective = "Besiegt Archimonde und erhaltet dadurch das Siegel des Erwachens.", progress = "Archimonde selbst... Auf was haben wir uns da eingelassen?", completion = "Solch eine Macht habe ich noch nie zuvor verspürt...\n\n<Y'mera hält den Splitter vorsichtig in ihren Händen.>\n\nWir sollten ihn so schnell wie möglich zu Velen bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[47691] = { id = 47691, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keine Anhänger des Propheten", description = "Ich bin mir sehr sicher, dass Velen in der Nähe ist. Wir hätten es erfahren, wenn er in Gefangenschaft geraten wäre.\n\nAber dennoch müssen wir uns beeilen. Die Legion hat großes Interesse, ihn in die Hände zu bekommen, nachdem er ihnen so lange Widerstand geleistet hat. Mir graut vor der Vorstellung, was sie ihm antun würde.\n\nDeshalb werde ich Euch begleiten.\n\nWir werden Velen finden und ihm helfen, das Wappen des Wissens zu finden. Wenn wir nicht an seine Mission glauben, ist alles verloren.", sourceObjective = "Findet Velen.", completion = "Ich war gerade in Gedanken versunken.\n\n<Velen schaut Euch mit müdem Ausdruck an.>\n\nAber wir haben jetzt keine Zeit für Grübeleien. Wir müssen weiter.", sourceObjectiveStatus = "unverified-source-field" }
quests[47695] = { id = 47695, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verlockende Lieder", description = "Sirenen bedeuten nichts als Ärger! Sie tun nichts anderes, als unsere Männer zu entführen, die wir dann nie wiedersehen. Wie soll ich denn meine Waren zügig nach Boralus bekommen, wenn die sich hier herumtreiben?\n\nDa Ihr ja gerade auf dem Weg da runter seid... Könntet Ihr ihre Reihen nicht ein wenig lichten?", sourceObjective = "Tötet 8 klagende Sirenen an der Nebelklippenküste.", sourceObjectiveStatus = "unverified-source-field" }
quests[47696] = { id = 47696, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krag'wa der Schreckliche", description = "Euer letzter Angriff hat die Bluttrolle verärgert. Jetzt entsenden sie eine Armee, um alles zu erobern. Sie kommen zu spät! Ich bin Krag'wa! Ich werde nicht gefressen, sondern ich fresse!\n\nTrefft mich am Ufer des Klingenschlundflusses. Ihr werdet meine Macht bezeugen und ich die Eure.", sourceObjective = "Nutzt Krag'was Macht, um den Gegenangriff der Bluttrolle aufzuhalten.", progress = "Erkennt Ihr meine Macht jetzt?", completion = "Die Wilden fliehen beim Anblick von Krag'wa! Das erfreut mich!\n\nDoch sie werden bald in noch größeren Scharen zurückkommen, wenn wir ihren dunklen Gott nicht aufhalten. Solange Ihr gegen sie kämpft, gewähre ich Euch meinen Segen.\n\nWenn der Tag der Abrechnung kommt, könnt Ihr Euch meiner Unterstützung gewiss sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[47697] = { id = 47697, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krag'was Hilfe", description = "Sehr gut, {name}!\n\nVor unsrem Aufbruch, hab ich gehört, dass Prinzessin Talanji aufm Weg zum Trübsumpf war. Sie müsste jetzt schon dort sein.\n\nBesser wir mach'n uns jetzt aufn Rückweg. Sie wird's kaum erwart'n können, die Geschichte über Euren Erfolg zu hör'n!", sourceObjective = "Meldet Prinzessin Talanji Euren Erfolg.", completion = "Krag'wa wird im bevorstehenden Kampf 'n mächtiger Verbündeter sein. Wenn die Bluttrolle einmal besiegt sin', kommen sicher viele Zandalari zurück, um ihn zu verehr'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[47704] = { id = 47704, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fressattacke der Ranishu" }
quests[47705] = { id = 47705, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinter den Linien der Legion" }
quests[47706] = { id = 47706, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagd auf König K'tal", description = "Jäger! In dieser Herausforderung geht's um den König des Reservats.\n\nKönig K'tal is'n mächtiger Jäger, schlau un' schnell. Der Jäger, der mir den Kopf des Königs bringt, wird mit Gold und Ehre überhäuft.", sourceObjective = "Erbeutet den Schädel des K'tal.", progress = "Erfolgreiche Jagd.", completion = "Beeindruckend. Der König wurde vom Thron gestoß'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[47707] = { id = 47707, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abschmelzen" }
quests[47709] = { id = 47709, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das große Rennen von Gnomeregan", description = "Seid Ihr bereit für das große Rennen heute, {name}?\n\nJedes Jahr versammeln sich Gnome aus aller Welt, um von Gnomeregan bis nach Beutebucht zu laufen.\n\nDas erinnert uns daran, dass kein Hindernis zu groß ist, auch nicht für uns. Ob man langsam oder schnell rennt, allein oder mit Freunden, man kommt ans Ziel, solange man nur weiter macht. Also vorwärts, dehnt Euch und dann los! Zeigt der Welt, aus welchem Holz wir Gnome geschnitzt sind!", sourceObjective = "Tragt ein Rennen zur Beutebucht aus.", completion = "Ein kleiner Schritt für {name}, ein großer Schritt für die Gnomheit!", sourceObjectiveStatus = "unverified-source-field" }
quests[47711] = { id = 47711, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kopf der Schlange", description = "Als ich das Gebiet ausgekundschaftet habe, habe ich einen großen, gepanzerten Naga gesehen, der den Rest der Schlangen befehligt hat. Ich will ja keine wilden Behauptungen aufstellen, aber das wird wohl der Anführer sein.\n\nSolange die Naga einen Kommandanten haben, sind unsere Einsätze hier in Gefahr. Schaltet ihn aus.", sourceObjective = "Tötet Lord Slithin am Zertrümmerten Übergang.", completion = "Gute Arbeit. Damit sollten wir etwas weniger unter Druck stehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[47712] = { id = 47712, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Verwüster" }
quests[47715] = { id = 47715, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[47716] = { id = 47716, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durchsuchung der Ruinen", description = "Diese Dünen sin' voller Assassinen. Nirgendwo is' es sicher, aber wir müss'n weiter.\n\nDie Ruinen sin' nich' weit von hier. \n\nSetz'n wir unsre Suche zu Fuß fort.", sourceObjective = "Findet Julwaba in Zul'Ahjin.", completion = "Serrik is' vom Gift geschwächt. Uns rennt die Zeit weg.", sourceObjectiveStatus = "unverified-source-field" }
quests[47720] = { id = 47720, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ewige Rache" }
quests[47724] = { id = 47724, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Belagert" }
quests[47725] = { id = 47725, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Grabmal des Sargeras: Aegwynns Pfad", description = "Als wir das Grabmal versiegelten, überließ ich das letzte Stück von Sargeras' Gefängnis der wachsamen Maid. Damit könntet Ihr Euch im Grabmal frei bewegen, doch ich weiß nicht, was aus seiner Hüterin geworden ist, und habe schlimme Befürchtungen.", sourceObjective = "Sammelt 4 Fragmente des Wächtersiegels von der wachsamen Maid im Grabmal des Sargeras auf dem Schwierigkeitsgrad 'Normal'.", progress = "Ohne die Macht des Siegels können wir meine Zauberschutze nicht umgehen.", completion = "Mit den Überresten dieses Siegels können wir die Zauberschutze bannen und mein Sanktum betreten.", sourceObjectiveStatus = "unverified-source-field" }
quests[47726] = { id = 47726, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Grabmal des Sargeras: Aegwynns Pfad", description = "Als wir das Grabmal versiegelten, überließ ich das letzte Stück von Sargeras' Gefängnis der wachsamen Maid. Damit könntet Ihr Euch im Grabmal frei bewegen, doch ich weiß nicht, was aus seiner Hüterin geworden ist, und habe schlimme Befürchtungen.", sourceObjective = "Sammelt 4 Fragmente des Wächtersiegels von der wachsamen Maid im Grabmal des Sargeras auf dem Schwierigkeitsgrad 'Heroisch'.", progress = "Ohne die Macht des Siegels können wir meine Zauberschutze nicht umgehen.", completion = "Mit den Überresten dieses Siegels können wir die Zauberschutze bannen und mein Sanktum betreten.", sourceObjectiveStatus = "unverified-source-field" }
quests[47727] = { id = 47727, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Grabmal des Sargeras: Aegwynns Pfad", description = "Als wir das Grabmal versiegelten, überließ ich das letzte Stück von Sargeras' Gefängnis der wachsamen Maid. Damit könntet Ihr Euch im Grabmal frei bewegen, doch ich weiß nicht, was aus seiner Hüterin geworden ist, und habe schlimme Befürchtungen.", sourceObjective = "Sammelt 4 Fragmente des Wächtersiegels von der wachsamen Maid im Grabmal des Sargeras auf dem Schwierigkeitsgrad 'Mythisch'.", progress = "Ohne die Macht des Siegels können wir meine Zauberschutze nicht umgehen.", completion = "Mit den Überresten dieses Siegels können wir die Zauberschutze bannen und mein Sanktum betreten.", sourceObjectiveStatus = "unverified-source-field" }
quests[47728] = { id = 47728, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talestra die Grässliche" }
quests[47733] = { id = 47733, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verrat der Loasprecherin", description = "Hört zu, Fremdling. Ich hab nich' mehr viel Zeit.\n\nIch war im Dorf, als Zolani den König zu uns brachte. Er sagte, es muss geheim bleib'n, sonst wird Zul uns aufspür'n.\n\nJetz' schaut Euch um. Sie ham uns gefund'n!\n\nAber ich weiß... das war nich' das Werk des Propheten. Unsre Loasprecherin hat Zolani ihr Wort gegeb'n und wollte uns helf'n, aber sie hat uns hinterlistig verrat'n.\n\nKihara ist schuld, dass wir jetz' sterb'n. Sie is' für all das verantwortlich!\n\nTötet sie... Lasst sie bezahl'n!", sourceObjective = "Tötet Loasprecherin Kihara.", progress = "Wir müss'n uns auf die Genesung des Königs konzentrier'n, {name}.", completion = "Diese Schlange von Frau hat Zul geholf'n den König aufzuspür'n! Es freut mich, dass sie tot is', obwohl ich sie lieber eigenhändig erschlag'n hätt.\n\n<Zolani spuckt.>\n\nBwonsamdi kann sie behalt'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[47734] = { id = 47734, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gemeinsame Ketzerei", description = "Rezan kämpft geg'n seine Fesseln an, aber wir könn' ihn nich' erreich'n.\n\nDie Mogu, die Zul hierhergeruf'n hat, ham 'nen Schild errichtet, geg'n den meine Magie nutzlos is'. Findet un' tötet die Kreatur'n, die zwischen mir un' mei'm Loa steh'n.\n\nIch muss mich für den Kampf ausruh'n, der uns bevorsteht. Am Ende des Tages wird der Hass von ZWEI Königen auf sie niedergeh'n.", sourceObjective = "Tötet Seelenfetzer Gao'tan und Dunkelwirker Ji'tan.", completion = "Gut. Der Weg voraus is' frei.", sourceObjectiveStatus = "unverified-source-field" }
quests[47735] = { id = 47735, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uralte Tortollanerarznei", description = "Aha, ja, die Situation erlaubt keinen Aufschub. Wir müssen schnell handeln, aber nicht voreilig.\n\nEs gibt einen Weg, Rastakhan zu retten, aber dieser erfordert drei ganz bestimmte Zutaten. Also hört gut zu, mein Kind.\n\nDie erste Zutat ist Schaum aus dem Maul einer Krabbe. Je älter und reifer, desto besser.\n\nDie zweite Zutat ist der Stachel eines Kugelfischs. Schön giftig!\n\nDie dritte und letzte Zutat ist die Schuppe eines Brutosaurus.\n\nWarum, fragt Ihr? Nun, das ist das Geheimnis meines Volkes, {name}. Die Langlebigkeit erfordert so viel Fürsorge wie eine seltene Blume... Man braucht viel Übung und Geduld und muss sehr vorsichtig vorgehen.", sourceObjective = "Sammelt einen giftigen Kugelfischstachel, eine Brutosaurusschuppe und Schaum einer alten Krabbe für Jol den Uralten.", progress = "Die Qualität der Heilung hängt stark von der Qualität der Zutaten ab.", completion = "Die sollten genügen. Ich werde Euch zu gegebener Zeit erklären, welchen Zweck sie erfüllen.", sourceObjectiveStatus = "unverified-source-field" }
quests[47736] = { id = 47736, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Köpfe werden rollen", description = "Zuls Streitkräfte woll'n sich den Tempel des Loas der Könige untern Nagel reiß'n.\n\nIhr müsst diesen Verrätern deutlich mach'n, welche Konsequenzen ihr Handeln nach sich zieht.\n\nBefreit den Tempel von dem Schmutz, der ihn entweiht. Vernichtet alle, die dem Loa ins Antlitz spuck'n. Bringt mir ihre Köpfe, damit die anderen daran erinnert werd'n, was mit jenen passiert, die ihren Glauben und ihren König verrat'n.\n\nWenn Ihr mit den Unwürdigen fertig seid, kommt wieder zu mir. Rezans Altar liegt tief im Inneren des Tempelgeländes.\n\nDann werd'n in Rastakhans Namen einmal mehr die Köpfe roll'n!", sourceObjective = "Sammelt 12 Köpfe von Zandalariverrätern.", progress = "Wird Zeit, diesen Verrätern 'ne deutliche Botschaft zu schick'n.", completion = "Das is' 'ne Botschaft, die sie versteh'n werd'n. Man muss nur ihre Sprache sprech'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[47737] = { id = 47737, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Tempel von Rezan", description = "Die Worte des Chronisten sin' entsetzlich. Wenn Zul tatsächlich Rezan opfern will...\n\nDas darf nicht passier'n! Ich werd meinen Loa mit meinem Leben verteidig'n.\n\nKommt, {name}, wir geh'n zum Tempel von Rezan. Diese Ketzerei muss sofort ein Ende find'n.", sourceObjective = "Trefft Euch mit König Rastakhan am Tempel von Rezan.", completion = "<Rastakhan starrt die Leiche des Priesters vor ihm finster an.>\n\nZul wird dafür bezahl'n. Wer ihm folgt, wird leid'n. Das schwör ich.", sourceObjectiveStatus = "unverified-source-field" }
quests[47738] = { id = 47738, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Wille des Loas", description = "Jols Heilmittel hat Rastakhans Fleisch geheilt. Aber sein Geist is' immer noch verlor'n. Nur eins kann ihn jetzt noch aufhalt'n.\n\nDer Tod.\n\nEr wandelt in Bwonsamdis Schatten. Wir könn' vorerst nichts tun. Aber... er gehört 'nem andren Loa. Einem, der seinen Gläubigen Leb'n schenkt.\n\nIhr müsst Rezan, den Loa der Könige, anruf'n un' ihn bitt'n, Rastakhans Seele zurückzufordern.\n\nDen Pfad da hoch findet Ihr meine Unterkunft. Stellt diesen Götzen auf un' wartet dann. Mit 'n bisschen Glück hilft er uns.\n\nWenn nich'... War schön, Euch kennenzulern'n.", sourceObjective = "Stellt einen Götzen von Rezan bei Jamils Unterkunft auf und überzeugt Rezan, Rastakhans Seele zurückzuholen.", completion = "<Rastakhan lächelt Euch grimmig zu.>\n\nIhr seht aus, als hättet Ihr einen Loa geseh'n. Ich kenn das Gefühl. Rezan und ich hab'n einiges zu besprechen, wenn wir uns wiederseh'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[47739] = { id = 47739, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Geruch der Vergeltung", description = "Ich kenn meinen König un' ich weiß, dass er 'n starken Willen hat. Sein Geist kämpft mit dies'm Verrat un' die Verwirrung treibt ihn etwas zu nah an die Schwelle des Todes heran.\n\nWir müss'n ihn an seine Bestimmung erinnern. Seine Wut.\n\nIch hab aus dem Dorf unter uns Schreie der Angst gehört. Zuls Anhänger foltern die Bewohner Zeb'aharis, während sie ihn such'n. Tötet die, die seinen Leuten Leid antun, und bringt mir ihr Blut.\n\nVielleicht lässt der Geruch der Vergeltung den Teufelssaurier in Rastakhan wiederaufleb'n.", sourceObjective = "Sammelt 12 Einheiten Verräterblut von Zuls Anhängern in Zeb'ahari.", progress = "Ich hoff, wir sin' nich' zu spät, {name}.", completion = "Der Geruch von Blut wird 'nen Teufelssaurier immer weck'n. Un' noch besser geht's mit Blut von Verrätern.", sourceObjectiveStatus = "unverified-source-field" }
quests[47740] = { id = 47740, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haus des Königs", description = "Rezan ruft mich. Und ich werd ihm antwort'n. Aber erst müsst Ihr mir helf'n.\n\nUnsere Loa segnen uns mit vielen Gaben und wir danken es ihnen mit Huldigungen. Opfergaben und Götzen sind Werkzeuge für uns, um ihre Gunst zu erhalt'n, aber unseren Loa bedeut'n sie noch viel mehr.\n\nSie sind Quellen der Kraft.\n\nZuls Hunde ham begonnen, die großen goldenen Statuen zu entweih'n, die Rezan gewidmet sind. Sogar jetzt spür ich, wie seine Kräfte schwind'n.\n\nIhr müsst sie aufhalt'n und die Götzen des großen Jägers läutern. Lehrt sie, Respekt vor dem Haus vom König zu ham.", sourceObjective = "Läutert die 3 Statuen des Rezan.", completion = "Mein Loa is' noch nich' tot. Sorgt dafür, dass das so bleibt.", sourceObjectiveStatus = "unverified-source-field" }
quests[47741] = { id = 47741, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wer den Loa opfert", description = "Rezans Macht schwindet. Meine Thronräuber ham ihr Ziel fast erreicht.\n\nIch hab von den Schrecken von Zul'Drak geles'n und ich hab geseh'n, wohin diese Taten führ'n. Dass einer meiner eigenen Leute für diese unaussprechliche Ketzerei verantwortlich is', kann ich immer noch nicht fass'n.\n\n<Rastakhan knurrt vor Wut.>\n\nKommt! Wir werd'n diesem Verräter, der allen Loa ins Gesicht spuckt, ein Ende setz'n!\n\nDi chuka Rezan!", sourceObjective = "Tötet Vilnak'dor und haltet die Opferung von Rezan auf.", completion = "<Rezan atmet schwer, während er sich von der Raserei erholt. Er ist mit Gedärm bedeckt.>\n\nKetzer.", sourceObjectiveStatus = "unverified-source-field" }
quests[47742] = { id = 47742, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zuls Meuterei", description = "Ein Schiff wie die Rastakhans Macht würd niemals ohne ihre eig'ne Mannschaft in See stech'n.\n\nDas kann nur bedeut'n, dass die Zandalari an Bord der Intrige von Zul zum Opfer gefall'n sind und ebenfalls ihren König verrat'n ham.\n\nBegebt Euch auf mein Schiff und tötet alle, die sich gegen ihren König gestellt ham. Es wird keine Gefangenen geb'n.\n\nFür Meuterei gibt's nur eine Strafe: den Tod!", sourceObjective = "Tötet 10 meuternde Zandalaritrolle auf dem Flaggschiff Rastakhans Macht.", completion = "Eure Hände sind blutig. Gut. Das is' der Preis für Meuterei.", sourceObjectiveStatus = "unverified-source-field" }
quests[47743] = { id = 47743, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Kind von Licht und Schatten", description = "Es ist so weit, {name}.\n\nXe'ra ist zu uns zurückgekehrt. Wir haben das Herz des Lichts. Wir haben ihren Auserwählten.\n\nKommt, lasst uns sie erneuern. Lasst uns einen hellen, neuen Weg gegen unsere Feinde beschreiten.\n\nSprecht mich an, wenn Ihr bereit seid.", sourceObjective = "Sprecht mit Turalyon, um Xe'ra wiederzubeleben.", completion = "Das hätte ich von Xe'ra nicht erwartet. Und ebenso wenig hätte ich Illidans Reaktion voraussehen können.\n\nWir müssen dafür sorgen, dass diese Ereignisse unseren Verbündeten nicht all ihren Mut nehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[47744] = { id = 47744, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tabak, Fleisch und hübsche Blümchen", description = "Der hintere Teil der Stadt ist abgeriegelt. Und ja, ich mag einen Schlüssel haben, aber ich kenne Euch nicht.\n\n<Emery klopft behutsam auf seine Tasche.>\n\nAlso hört zu, Ihr seht ja ehrlich aus. Holt mir ein wenig Wildbret, Pfeifentabak und ein Bündel gelbe Blümchen, dann mach' ich vielleicht einfach eine Ausnahme.", sourceObjective = "Beschafft gedörrtes Salzwildbret, Grimms spezielle Pfeifentabakmischung und einen Strauß Ringelblumen.", progress = "Ihr seid wohl nicht in Eile, was?", completion = "Der Tabak und das Fleisch sind für mich. Die Blumen sind allerdings für die Kinder im Waisenhaus am Ende der Straße.", sourceObjectiveStatus = "unverified-source-field" }
quests[47745] = { id = 47745, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ja klar, für die Kinder", description = "Kennt Ihr Waisenmatrone Meliana? Sie ist eine wahre Göttin, herabgestiegen, um Lordaeron Demut zu lehren. Ihr Haar, diese Wangenknochen und...\n\n...und wie dem auch sei, diese Blumen sind für die Kinder des Waisenhauses, in dem sie arbeitet. Sagt Meliana, sie sind von mir. Für die Kinder.", sourceObjective = "Überbringt den Strauß Ringelblumen Waisenmatrone Meliana.", progress = "Was haben wir denn hier?", completion = "Die sind vermutlich von Emery?\n\n<Meliana errötet.>\n\nDieses Dummerchen. Aber seine Beharrlichkeit ist schon bewundernswert...", sourceObjectiveStatus = "unverified-source-field" }
quests[47746] = { id = 47746, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sicher versteckt", description = "Habt... Habt Ihr das gesehen? Prinz Arthas hat diese Person gerade kaltblütig niedergestreckt! Mitten auf offener Straße!\n\n<Meliana gewinnt ihre Fassung zurück.>\n\nIch muss die Kinder beschützen. Bitte, helft uns, Besucher. Ich brauche ein Gewehr, Verbände und etwas gedörrtes Wildbret.\n\nKinder! Schnell, ins Haus!", sourceObjective = "Beschafft ein instandgesetztes Militärgewehr, einfache Stoffbandagen und gedörrtes Salzwildbret.", progress = "Die Kinder haben oberste Priorität.", completion = "Ich weiß nicht, wie lange wir uns im Waisenhaus verstecken müssen, aber ich werde die Kinder nicht nach draußen lassen, während unser Prinz wie ein Wahnsinniger durch die Straßen irrt.", sourceObjectiveStatus = "unverified-source-field" }
quests[47747] = { id = 47747, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seuchen ausbrennen", description = "Noch eine letzte Bitte, <Fremder/Fremde>. Ich habe gesehen, was draußen los ist, und von dieser \"Seuche\" gehört. Ich werde nicht kampflos aufgeben.\n\nHinten hab ich genug Rum, um die ganze Kneipe in Brand zu stecken, aber mir fehlen die Werkzeuge, um es sicher zu bewerkstelligen. Besorgt mir einen Feuerstein und ein Stück Seil, dann gebe ich Euch meinen Schlüssel zu den Gassen von Stratholme.", sourceObjective = "Beschafft einen funkenden Feuerstein und ein schweres Strohseil.", progress = "Ob verrückter Prinz oder sabbernder Zombie... Kampflos überlasse ich diese Kneipe niemandem!", completion = "Das wird reichen, {class}.\n\nNehmt diesen Schlüssel. Ihr habt ihn Euch verdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[47748] = { id = 47748, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Holing Up Complete" }
quests[47749] = { id = 47749, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Fight Plague With Fire Complete" }
quests[47750] = { id = 47750, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Für Emery", description = "Wir haben hier schon jede Menge Essen. Wenn Ihr Euch in die Straßen wagt, bringt dieses Wildbret doch bitte zu dem großen Dummerchen in der Kneipe.\n\nSagt ihm, es ist von den Kindern.", sourceObjective = "Liefert das gedörrte Salzwildbret an Emery Neill.", progress = "Sagt, was habt Ihr denn da?", completion = "Von den Kindern, sagt Ihr?\n\n<Emery bemüht sich, sein Grinsen zu verbergen, während er das Dörrfleisch einsteckt.>", sourceObjectiveStatus = "unverified-source-field" }
quests[47751] = { id = 47751, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Winterhauchgeschenk" }
quests[47754] = { id = 47754, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leicht geröstet", description = "Könnt Ihr mich hören, {name}? Gut.\n\nDas Urteil des Lichts ist jetzt auf der Vindikaar installiert. Wir sollten sofort in der Lage sein, sein Potenzial einzusetzen.\n\nWir können es nutzen, um das Geröll vor der Xenedar aus dem Weg zu räumen und gleichzeitig unsere Feinde zu vernichten.\n\nUnd wie bei allen neuen Technologien müssen wir auch diese zunächst testen. Und zwar gründlich. Da unten sollten sich Euch jede Menge Ziele bieten.", sourceObjective = "Verwendet das Urteil des Lichts, um das Geröll zu zertrümmern, das den Zugang zur Xenedar blockiert.", completion = "Ausgezeichnet. Der Weg ist frei.", sourceObjectiveStatus = "unverified-source-field" }
quests[47755] = { id = 47755, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefangen und betört", description = "Ihr müsst mir helfen! Ich und meine Männer waren mit unserer Lieferung spät dran. Deshalb wollten wir eine Abkürzung durch diese Grotte dort vorne nehmen. Aber, oje... Das war ein Fehler. Dort wimmelt es nur so vor Sirenen!\n\nWenn es etwas gibt, das meine Männer noch mehr mögen als Frauen, dann ist es Grog! Bitte, nehmt etwas mit. Versucht, sie damit wieder zur Vernunft zu bringen. Vielleicht hilft es, sie ein wenig aufzurütteln, um den Zauber zu schwächen.", sourceObjective = "Befreit 6 bezauberte Matrosen an der Nebelklippenküste.", completion = "Meine Männer haben sich bei mir zurückgemeldet. Danke, dass Ihr sie befreit habt, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[47756] = { id = 47756, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befreiung der Goldkelch" }
quests[47767] = { id = 47767, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Death Metal Knight" }
quests[47771] = { id = 47771, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suche nach dem Fernschützen", description = "Wir brauchen ein größeres Geschütz, wenn wir Xe'ra befreien wollen.\n\nEiner der anderen Bunker ist näher an der Xenedar abgestürzt. Wenn Baraat darin war, hat er sicherlich schon begonnen, die Gegend auszukundschaften. Vielleicht hat er bereits die Hauptkanone des Schiffs gefunden.\n\nKönntet Ihr auch nach ihm sehen, wenn Ihr Euch auf den Weg dorthin macht?", sourceObjective = "Findet Baraat den Fernschützen.", completion = "Wir stehen hier unter zu großem Druck. Und dabei sind wir so nah dran...", sourceObjectiveStatus = "unverified-source-field" }
quests[47772] = { id = 47772, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kanonenfeuer setzt den Himmel in Flammen", description = "Oh! Das bin ja ich! Und {name}, oder? Ich erinnere mich daran!\n\nIch war auf einmal mitten in einer Schlacht zwischen Horde und Allianz, was NORMALERWEISE keine große Sache wäre, wenn da nicht diese riesige Kanone gewesen wäre, die immer auf mich zielte, wenn ich versuchte wegzufliegen.\n\nKönntet Ihr sie vielleicht für mich ausschalten?", sourceObjective = "Zerstört die Belagerungskanone der Horde.", completion = "Ihr habt es geschafft! Und jetzt schnell... Wenn ich mich richtig erinnere, habt Ihr nicht mehr viel Zeit!", sourceObjectiveStatus = "unverified-source-field" }
quests[47773] = { id = 47773, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kanonenfeuer setzt den Himmel in Flammen", description = "Oh! Das bin ja ich! Und {name}, oder? Ich erinnere mich daran!\n\nIch war auf einmal mitten in einer Schlacht zwischen Horde und Allianz, was NORMALERWEISE keine große Sache wäre, wenn da nicht diese riesige Kanone gewesen wäre, die immer auf mich zielte, wenn ich versuchte wegzufliegen.\n\nKönntet Ihr sie vielleicht für mich ausschalten?", sourceObjective = "Zerstört die Belagerungskanone der Allianz.", progress = "Habt Ihr es geschafft? Die Kanone der Allianz muss deaktiviert sein, damit ich entkommen kann.", completion = "Ihr habt es geschafft! Und jetzt schnell... Wenn ich mich richtig erinnere, habt Ihr nicht mehr viel Zeit!", sourceObjectiveStatus = "unverified-source-field" }
quests[47790] = { id = 47790, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ungezügelte Kraft", description = "Die Freisetzung der zuvor im Nachtbrunnen gefangenen Energie hat... den Einfluss von Aman'thul überall auf den Verheerten Inseln verkompliziert. Leider sind damit die Ergebnisse aller meiner vorherigen Arbeiten ungültig, so wie der Inhalt dieser Phiole.\n\nIch muss den Grund für diese Veränderung erfahren! Bitte bringt mir weitere Proben, damit ich meine Arbeit fortsetzen kann. Es versteht sich von selbst, dass Ihr von allen Durchbrüchen, die ich vielleicht mache, profitieren werdet.", sourceObjective = "Bringt 50 wabernde Essenzen zu Arkanomant Vridiel.", progress = "Das Volk Suramars hat 10.000 Jahre damit verbracht, die ruhenden Energien eines toten Titanen anzuzapfen. Ich frage mich, ob je einer von ihnen darüber nachgedacht hat, was passiert, wenn sie plötzlich damit aufhören.", completion = "Ich habe die Mixtur stabilisieren können, ohne ihre Potenz zu schwächen. Das war gar nicht so einfach. Ich hoffe also, Ihr wisst die harte Arbeit zu würdigen, die uns so weit gebracht hat.\n\nIch habe ein sehr ungutes Gefühl, was die Quelle für diese Störung betrifft. Ich hätte eigentlich erwartet, dass die Freisetzung von Aman'thuls Kraft für Harmonie und nicht für Chaos sorgen würde.", sourceObjectiveStatus = "unverified-source-field" }
quests[47791] = { id = 47791, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ungezügelte Kraft", description = "Es ist zutiefst beunruhigend, dass die Kraft von Aman'thul immer instabiler wird. Wir müssen diese Sache weiter verfolgen.\n\nIst diese Volatilität die Folge der Verderbnis der Legion? Nein, dafür war die Zeit zu kurz, irgendetwas anderes muss...\n\n<Vridiel ist in seinen Gedanken versunken und sieht Euch gar nicht mehr.>", sourceObjective = "Bringt 50 wabernde Essenzen zu Arkanomant Vridiel.", progress = "Ich muss die Quelle dieser Störung in diesen Proben aufdecken.", completion = "Das treibt mich noch in den Wahnsinn! Ich bin dem Durchbruch in dieser Sache noch nicht näher. So ein Versagen ist unentschuldbar!\n\n<Vridiel atmet tief ein und beruhigt sich.>\n\nIch danke Euch, {name}. Solche Rückschläge dürfen mich nicht von weiteren Versuchen abhalten. Bitte nehmt dies. Ihr habt sicherlich Verwendung dafür.", sourceObjectiveStatus = "unverified-source-field" }
quests[47793] = { id = 47793, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die verdorbene Probe", description = "<Ihr nehmt eine Phiole mit zähflüssiger, schwarzer Flüssigkeit an Euch. Der Inhalt reagiert auf Eure Berührung und kocht einen Moment lang brodelnd auf, bevor er mit einem stetigen Leuchten zur Ruhe kommt. In diesem Zustand sieht die Substanz Arkwein ähnlich, doch die Reaktion erinnert Euch an die Reduktion von Obliterum.\n\nIhr steckt die Phiole in Eure Tasche. Jemand in Dalaran, der mit der Obliterumschmiede vertraut ist, weiß eventuell mehr.>", sourceObjective = "Bringt die verdorbene Probe zu Arkanomant Vridiel in Dalaran auf den Verheerten Inseln.", completion = "Das ist beängstigend. Gul'dans Niederlage könnte weitaus fundamentalere Kräfte gestört haben, als irgendjemand ahnen konnte.\n\nHmm... Vielleicht können wir das auch zu unserem Vorteil nutzen.", sourceObjectiveStatus = "unverified-source-field" }
