quests[47805] = { id = 47805, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stolen Time" }
quests[47806] = { id = 47806, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Draconic Assistant" }
quests[47807] = { id = 47807, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sorge um meine Freunde", description = "Ich habe gehört, dass es am schwarzen Drachenschrein Probleme geben soll. Ich weiß, ich bin ein Bronzedrache, aber trotzdem...! Manchmal mache ich mir Sorgen um sie! Sie waren ja nicht IMMER schon so schlecht gelaunt.\n\nWenn Ihr vielleicht gerade auf dem Weg dorthin seid... könntet Ihr womöglich mal nachschauen, was das für Störungen sind?", sourceObjective = "Tötet Zorathides am Obsidiandrachenschrein.", completion = "Es war ein Schreckenslord? Das ist... ungewöhnlich. Also, ich weiß natürlich, dass wir hier in Nordend sind und auferstandene Skelette nicht so selten vorkommen... Aber Dämonen?\n\nNun, ja! Danke, dass Ihr die Zeit gefunden habt, meine Sorgen zu mindern.", sourceObjectiveStatus = "unverified-source-field" }
quests[47808] = { id = 47808, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wandelnde Tote", description = "Grüße, {race}! Ich weiß, dass Ihr im Dienste der Bronzenen steht, aber ich habe ein Anliegen an Euch.\n\nDer Rubindrachenschrein wird von Untoten heimgesucht. Die Wächter meines Schreins wurden überrascht und wir riskieren Verluste, wenn wir nicht schleunigst eingreifen. Würdet Ihr uns vielleicht helfen?", sourceObjective = "Tötet Talar Eiseskälte am Rubindrachenschrein.", completion = "Ich danke Euch, {race}.\n\nIch weiß, dass Ihr im Auftrag des bronzenen Drachenschwarms hier seid. Vielleicht wird Euch dieses Geschenk auf Eurer Reise unterstützen.", sourceObjectiveStatus = "unverified-source-field" }
quests[47809] = { id = 47809, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leydunkelheit", description = "Eine seltsame, dunkle Störung wirkt auf die Leylinien im Drachenschrein meines Schwarms. Könntet Ihr Euch die Sache vielleicht einmal anschauen?", sourceObjective = "Tötet den Leerenkoloss am Azurdrachenschrein.", completion = "Euer Beistand wird hoch geschätzt.", sourceObjectiveStatus = "unverified-source-field" }
quests[47810] = { id = 47810, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verdunkelte Träume", description = "Die Urtume am Smaragddrachenschrein leiden in ihren Träumen. Ohne Ysera habe ich keine Gelegenheit, die Sache selbst zu untersuchen. Könntet Ihr mir helfen, den Smaragddrachenschrein von diesem Alptraum zu läutern?", sourceObjective = "Tötet Thalas Schlangendorn am Smaragddrachenschrein.", progress = "Ich weiß zu würdigen, dass Ihr Euch meine Sorgen anhört, {race}.", completion = "Dank Eures Eingreifens sind die Urtume wieder in friedvollen Schlaf gefallen. Ich danke Euch, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[47820] = { id = 47820, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stolen Time" }
