quests[47835] = { id = 47835, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Hand des Schicksals", sourceObjective = "Trefft Euch mit Eurer Eskorte zur Exodar in der Messerbucht.", completion = "Ich wusste, dass Ihr unter den ausgewählten Kämpfern sein würdet. Es wird mir eine Ehre sein, an Eurer Seite zu kämpfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[47844] = { id = 47844, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wiederkehrender Wahnsinn" }
quests[47851] = { id = 47851, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schicksal besiegeln: Ehrenabzeichen", progress = "Diese Siegel gewähren Euch eine zusätzliche Chance auf Schätze in Dungeons und Schlachtzügen, aber um welchen Preis? Andere zu töten, ist nicht ehrbar, und doch werden Ehrenabzeichen gesammelt? Mit diesen Abzeichen kann ich wohl zusätzliche Schätze gewinnen. Das ist das Angebot, das ich Euch unterbreite.\n\nDenkt daran, Ihr könnt pro Woche nur drei Siegel erwerben. Dieses hier zählt dazu. Nächste Woche habe ich andere im Angebot.", completion = "Ein einfacher Austausch mit vielschichtigen Ergebnissen. Das ist die Kunst des Geschäftemachens." }
quests[47853] = { id = 47853, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flankenmanöver", description = "Ich werde den Befehl über Fareeyas Leutnants übernehmen und Velen zum Wappen des Wissens begleiten. Seine Mission darf nicht fehlschlagen.\n\nEs erwartet uns ein alter Feind, einer, dem die Armee des Lichts schon viele Male begegnet ist. Talgath wird versuchen, uns aufzuhalten und unseren Rückzug zu verhindern.\n\nDas dürft Ihr nicht zulassen. Bringt in Erfahrung, woher seine Streitkräfte kommen und schneidet ihnen den Weg ab. Wir brauchen nur die Zeit, um hinein und wieder heraus zu gelangen.\n\nWir zählen auf Euch.", sourceObjective = "Schließt 3 Legionsportale.", completion = "<Velen starrt stumm auf die zertrümmerte Statue vor ihm.>", sourceObjectiveStatus = "unverified-source-field" }
quests[47854] = { id = 47854, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zorn des Hochexarchen", description = "Wenn es um die Legion geht, ist Gewalt immer die Lösung.\n\n<Turalyon erhebt seine Klinge mit düsterem Blick.>\n\nSie steht zwischen uns und Velen. Wenn wir tatenlos zusehen, wird nichts sie davon abhalten, ihn zu finden. Dies ist keine Zeit für Zurückhaltung.\n\nGemeinsam werden wir Chaos unter ihnen verbreiten.", sourceObjective = "Stört die Streitkräfte der Legion in den Gärten von Arinor.", completion = "Wenn ich eines über die Legion gelernt habe, dann, dass der Kampf gegen sie die einzige Option ist.\n\nEs war mir eine Freude, Euch an meiner Seite zu haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[47855] = { id = 47855, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was hätte sein können", description = "<Velen starrt beim Reden weiterhin die Statue an.>\n\nAls ich noch jung war, vor Tausenden von Jahren, traf ich eine Entscheidung.\n\nEine Entscheidung, die den Untergang meiner Welt zuließ. Eine Entscheidung, die mein Volk ins Exil trieb. Eine Entscheidung, die mich für immer von meinen geliebten Brüdern trennte.\n\n<Velen schüttelt den Kopf.>\n\nNoch kann ich nicht gehen. Erst muss ich mir das alles durch den Kopf gehen lassen.", sourceObjective = "Werdet Zeuge von Velens Erinnerung.", completion = "<Prophet Velen blickt Euch ausdrucksvoll an.>\n\nHabt Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[47856] = { id = 47856, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Quer durchs Universum", description = "Talgath. Einst durfte ich ihn als Verbündeten und Freund bezeichnen.\n\nAls die Zeit kam, in der wir Argus hinter uns lassen mussten, verließ ich mich auf ihn. Ich bat ihn, die anderen aufzufordern, mich zu begleiten.\n\nIch gab ihm alles, was er brauchte, um mich zu verraten und meine Anhänger abzuschlachten.\n\nIch weiß nicht, was diesen Hass in seinem Herzen lauern ließ, doch seine Intrigen zwangen mein Volk wiederholt, von Welt zu Welt zu flüchten. Er machte es zu seiner Aufgabe, uns durch das ganze Universum zu jagen.\n\nEs muss enden, {name}. Talgath muss sterben.", sourceObjective = "Besiegt Talgath.", completion = "Es ist vollbracht. Ein Unrecht unter vielen wurde endlich vergolten.", sourceObjectiveStatus = "unverified-source-field" }
quests[47858] = { id = 47858, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sicherheitsmaßnahmen: Aktiv" }
quests[47864] = { id = 47864, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schicksal besiegeln: Zusätzliche Ehrenabzeichen", progress = "Diese Siegel gewähren Euch eine zusätzliche Chance auf Schätze in Dungeons und Schlachtzügen, aber um welchen Preis? Andere zu töten, ist nicht ehrbar, und doch werden Ehrenabzeichen gesammelt? Mit diesen Abzeichen kann ich wohl zusätzliche Schätze gewinnen. Das ist das Angebot, das ich Euch unterbreite.\n\nDenkt daran, Ihr könnt pro Woche nur drei Siegel erwerben. Dieses hier zählt dazu. Nächste Woche habe ich andere im Angebot.", completion = "Ein einfacher Austausch mit vielschichtigen Ergebnissen. Das ist die Kunst des Geschäftemachens." }
quests[47865] = { id = 47865, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schicksal besiegeln: Haufen von Ehrenabzeichen", progress = "Diese Siegel gewähren Euch eine zusätzliche Chance auf Schätze in Dungeons und Schlachtzügen, aber um welchen Preis? Andere zu töten, ist nicht ehrbar, und doch werden Ehrenabzeichen gesammelt? Mit diesen Abzeichen kann ich wohl zusätzliche Schätze gewinnen. Das ist das Angebot, das ich Euch unterbreite.\n\nDenkt daran, Ihr könnt pro Woche nur drei Siegel erwerben. Dieses hier zählt dazu. Nächste Woche habe ich andere im Angebot.", completion = "Ein einfacher Austausch mit vielschichtigen Ergebnissen. Das ist die Kunst des Geschäftemachens." }
quests[47867] = { id = 47867, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zwei übers Meer", description = "Die Draenei haben ein Gefährt gebaut, mit dem wir sicher nach Argus gelangen können. Sie sammeln gerade eine Invasionsstreitkraft auf der Azurmythosinsel. \n\nWir werden das Meer überqueren und dort zu ihnen stoßen. Die Legion behält das Tor zu ihrer Welt sicher genau im Blick. Wir müssen den Überraschungseffekt bewahren.\n\nLasst es mich wissen, wenn Ihr bereit seid.", sourceObjective = "Sprecht mit Lady Liadrin, um zur Exodar aufzubrechen.", completion = "Möge das Licht uns alle an diesem Tage beschützen.", sourceObjectiveStatus = "unverified-source-field" }
quests[47868] = { id = 47868, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Nekropole", description = "Abgemacht is' abgemacht, und ich bleib nichts schuldig.\n\nBwonsamdi is'n mächtiger Loa, und um seine Aufmerksamkeit zu krieg'n, braucht Ihr'n mächtiges Ritual.\n\nIhr habt aber Glück. Ich weiß schon genau, was wir mach'n müss'n.\n\nBwonsamdis Tempel, die Nekropole, is' direkt nördlich von hier. Trefft mich im Innenhof, dann schau'n wir, dass wir Euch eine Audienz beim Loa des Todes besorg'n.", sourceObjective = "Sprecht mit Hanzabu im Innenhof der Nekropole.", completion = "Da seid Ihr ja. Wir sind bereit, anzufang'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[47870] = { id = 47870, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Toten schweigen", description = "Ich bin Mitarbeiter der Handelskompanie Aschenwind, der Nummer eins im Azerithandel. \n\nAls ich diesen Auftrag übernahm, hat mir niemand gesagt, dass es eine Reise ohne Wiederkehr werden würde!\n\nIch würde praktisch alles tun, um aus diesen Dünen zu entkommen... sogar mit Euch zusammenarbeiten.\n\nVielleicht können wir uns ja gegenseitig helfen.\n\nIch wäre bereit, Euch den Code für die Schließkassette des Kapitäns zu verraten, wenn Ihr mir helft, aus dieser elendigen Wüste zu entkommen.\n\nDamit mein Plan aufgeht, muss mein Expeditionsteam sterben. Ich kann nicht riskieren, dass sie irgendwem von meinem Verschwinden erzählen...", sourceObjective = "Tötet die verbliebenen Mitglieder von Randalls Expeditionsteam.", completion = "Ist es erledigt? Ich konnte Hendricks sowieso nie ausstehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[47871] = { id = 47871, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seefahrerausrüstung", description = "Dieses Boot ist vielleicht keine Schönheit, aber es wird mich zurück nach Boralus bringen. \n\nAber bevor ich die Seereise antreten kann, benötige ich ein paar Sachen. \n\nGlücklicherweise findet Ihr all dies im Aschenwindlager.", sourceObjective = "Sucht einen Seefahrerhut, eine nautische Karte und ein verwittertes Fernrohr.", progress = "Habt Ihr die Sachen bergen können, um die ich Euch gebeten habe?", completion = "Das sollte mir helfen, an mein Ziel zu gelangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[47873] = { id = 47873, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schatz des Käpt'ns", description = "Hm, ich bin sicher, Ihr habt es jetzt verstanden, richtig?\n\nIch wollte niemals die Mannschaft verlassen, ich wollte einfach nur im Rang aufsteigen. Dabei habt Ihr mir wirklich weitergeholfen.\n\nWenn wir schon beim Thema sind, wir hatten da ja noch die Sache mit Kapitän Hartfords Schließkassette...\n\nHier ist die Kombination, freiwillig bereitgestellt vom toten Kapitän. Wie ich versprochen hatte, sie ist Euer!\n\nUnd bitte erzählt niemandem etwas von unserem kleinen Handel, okay? So eine Kleinigkeit sollte doch eine so gewinnbringende Partnerschaft nicht trüben!", sourceObjective = "Plündert Kapitän Hartfords Schließkassette.", completion = "<Die Truhe öffnet sich knarzend.>", sourceObjectiveStatus = "unverified-source-field" }
